export function createManifest() {
  const svgIcon192 = 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 192 192" width="192" height="192"><rect width="192" height="192" rx="36" fill="' + encodeURIComponent(PALETTE.BG_DARK) + '"/><polygon points="96 28 156 64 156 128 96 164 36 128 36 64" fill="' + encodeURIComponent(PALETTE.SURFACE) + '" stroke="' + encodeURIComponent(PALETTE.BORDER_FOCUS) + '" stroke-width="8"/><circle cx="96" cy="96" r="32" fill="' + encodeURIComponent(PALETTE.MATH) + '"/><polygon points="96 74 114 108 78 108" fill="' + encodeURIComponent(PALETTE.GOLD) + '"/></svg>';

  const svgIcon512 = 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512"><rect width="512" height="512" rx="96" fill="' + encodeURIComponent(PALETTE.BG_DARK) + '"/><polygon points="256 74 416 170 416 342 256 438 96 342 96 170" fill="' + encodeURIComponent(PALETTE.SURFACE) + '" stroke="' + encodeURIComponent(PALETTE.BORDER_FOCUS) + '" stroke-width="20"/><circle cx="256" cy="256" r="86" fill="' + encodeURIComponent(PALETTE.MATH) + '"/><polygon points="256 196 304 290 208 290" fill="' + encodeURIComponent(PALETTE.GOLD) + '"/></svg>';

  return {
    name: "QUEST: Kentucky — Governor's Cup RPG",
    short_name: "QUEST: KY",
    description: "Browser RPG for grades 6-8 preparing for Kentucky Governor's Cup competition",
    start_url: "/",
    display: "standalone",
    orientation: "any",
    theme_color: PALETTE.BG_DARK,
    background_color: PALETTE.BG_DARK,
    icons: [
      {
        src: svgIcon192,
        sizes: "192x192",
        type: "image/svg+xml",
        purpose: "any maskable",
      },
      {
        src: svgIcon512,
        sizes: "512x512",
        type: "image/svg+xml",
        purpose: "any maskable",
      },
    ],
  };
}

export function createServiceWorker() {
  return `// Service Worker — Offline Shell & Asset Cache
const CACHE_NAME = 'quest-ky-shell-v1';
const SHELL_URLS = ['/', '/manifest.webmanifest'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(SHELL_URLS))
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
      )
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  const url = new URL(event.request.url);

  if (url.pathname === '/' || url.pathname === '/manifest.webmanifest') {
    event.respondWith(
      caches.match(event.request).then((cachedResponse) => {
        const fetchPromise = fetch(event.request).then((networkResponse) => {
          if (networkResponse && networkResponse.status === 200) {
            const responseClone = networkResponse.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(event.request, responseClone));
          }
          return networkResponse;
        }).catch(() => cachedResponse);
        return cachedResponse || fetchPromise;
      })
    );
  }
});
`;
}

const CLIENT_BUNDLE = "/* --- CONSTANTS & CONFIG --- */\n\n// src/data/constants.js — Centralized Project Constants\r\n// Single source of truth for dimensions, palette, subjects, and gameplay rules.\r\n\r\nconst VIEWPORT = {\r\n  LOGICAL_WIDTH: 320,\r\n  LOGICAL_HEIGHT: 240,\r\n  TILE_SIZE: 16,\r\n  MIN_TOUCH_TARGET: 48, // Minimum 48x48px for WCAG 2.5.5\r\n};\r\n\r\nconst PALETTE = {\r\n  // Canvas & UI Surfaces\r\n  BG_DARK: '#0F172A',         // Slate 900\r\n  SURFACE: '#1E293B',         // Slate 800\r\n  SURFACE_ELEVATED: '#334155',// Slate 700\r\n  SURFACE_ACCENT: '#475569',  // Slate 600\r\n  BORDER_SUBTLE: '#334155',   // Slate 700\r\n  BORDER_FOCUS: '#38BDF8',    // Sky 400\r\n  PARCHMENT: '#FEF3C7',       // Amber 100\r\n  PARCHMENT_BORDER: '#D97706',// Amber 600\r\n\r\n  // Text Tokens\r\n  TEXT_PRIMARY: '#F8FAFC',    // Slate 50\r\n  TEXT_SECONDARY: '#94A3B8',  // Slate 400\r\n  TEXT_DARK: '#0F172A',       // Slate 900\r\n\r\n  // Feedback Tokens\r\n  SUCCESS: '#10B981',         // Emerald 500\r\n  WARNING: '#F59E0B',         // Amber 500\r\n  ERROR: '#EF4444',           // Red 500\r\n  GOLD: '#FBBF24',            // Amber 400\r\n\r\n  // KAAC Governor's Cup Subjects\r\n  MATH: '#2563EB',            // Blue 600 (Cipher Caverns)\r\n  SCIENCE: '#059669',         // Emerald 600 (Verdant Wilds)\r\n  SOCIAL_STUDIES: '#D97706',  // Amber 600 (Kingdoms of Time)\r\n  LANGUAGE_ARTS: '#7C3AED',   // Violet 600 (Whispering Archives)\r\n  ARTS_HUMANITIES: '#DB2777', // Pink 600 (Gallery of Wonders)\r\n};\r\n\r\nconst SUBJECTS = {\r\n  MATH: {\r\n    id: 'math',\r\n    name: 'Mathematics',\r\n    color: PALETTE.MATH,\r\n    realm: 'Cipher Caverns',\r\n    boss: 'Number Golem',\r\n  },\r\n  SCIENCE: {\r\n    id: 'science',\r\n    name: 'Science',\r\n    color: PALETTE.SCIENCE,\r\n    realm: 'Verdant Wilds',\r\n    boss: 'Overgrown Guardian',\r\n  },\r\n  SOCIAL_STUDIES: {\r\n    id: 'social_studies',\r\n    name: 'Social Studies',\r\n    color: PALETTE.SOCIAL_STUDIES,\r\n    realm: 'Kingdoms of Time',\r\n    boss: 'Chrono Warden',\r\n  },\r\n  LANGUAGE_ARTS: {\r\n    id: 'language_arts',\r\n    name: 'Language Arts',\r\n    color: PALETTE.LANGUAGE_ARTS,\r\n    realm: 'Whispering Archives',\r\n    boss: 'Wordweaver',\r\n  },\r\n  ARTS_HUMANITIES: {\r\n    id: 'arts_humanities',\r\n    name: 'Arts and Humanities',\r\n    color: PALETTE.ARTS_HUMANITIES,\r\n    realm: 'Gallery of Wonders',\r\n    boss: 'Living Masterpiece',\r\n  },\r\n};\r\n\r\nconst SPACED_REPETITION = {\r\n  INTERVALS_DAYS: [1, 3, 7, 14, 30],\r\n  VERIFICATION_MIN_COUNT: 3, // Requires 3 distinct questions to verify mastery\r\n};\r\n\r\nconst TARGET_GRADE_BAND = '6-8'; // Middle Grades focus\n\n/* --- GAME DATA & GENERATORS --- */\n\n// src/data/game-data.js — Initial Game Data & Pseudonymous Generators\r\n// Child privacy: Zero PII. Adventurer handles are procedurally generated.\r\n\r\n\r\nconst HANDLE_PREFIXES = [\r\n  'Bluegrass', 'Cumberland', 'Berea', 'Derby', 'Cardinal',\r\n  'Redriver', 'Limestone', 'Mammoth', 'Goldenrod', 'Paducah'\r\n];\r\n\r\nconst HANDLE_ROLES = [\r\n  'Wizard', 'Scholar', 'Ranger', 'Pioneer', 'Alchemist',\r\n  'Chronologer', 'Sage', 'Navigator', 'Wordweaver', 'Guardian'\r\n];\r\n\r\n/**\r\n * Procedurally generates a child-safe pseudonymous adventurer handle.\r\n * Follows COPPA compliance: Zero PII, no real names or identifiers.\r\n * @param {() => number} [rng=Math.random]\r\n * @returns {string} e.g. \"BluegrassWizard42\"\r\n */\r\nfunction generateAdventurerHandle(rng = Math.random) {\r\n  const prefix = HANDLE_PREFIXES[Math.floor(rng() * HANDLE_PREFIXES.length)];\r\n  const role = HANDLE_ROLES[Math.floor(rng() * HANDLE_ROLES.length)];\r\n  const num = Math.floor(rng() * 90) + 10;\r\n  return `${prefix}${role}${num}`;\r\n}\r\n\r\n/**\r\n * Initial Starter Quests aligned with Governor's Cup subject realms.\r\n */\r\nconst STARTER_QUESTS = [\r\n  {\r\n    id: 'quest_math_01',\r\n    subjectId: 'math',\r\n    title: \"The Cipher's Enigma\",\r\n    realm: SUBJECTS.MATH.realm,\r\n    color: SUBJECTS.MATH.color,\r\n    description: 'Investigate strange numerical runes in the Cipher Caverns.',\r\n    status: 'active',\r\n    progress: '0 / 3 Runes Decoded',\r\n    rewardXp: 150,\r\n    rewardGold: 25,\r\n  },\r\n  {\r\n    id: 'quest_science_01',\r\n    subjectId: 'science',\r\n    title: 'Flora of the Verdant Wilds',\r\n    realm: SUBJECTS.SCIENCE.realm,\r\n    color: SUBJECTS.SCIENCE.color,\r\n    description: 'Catalog photosynthetic anomalies along the wild moss river.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 120,\r\n    rewardGold: 20,\r\n  },\r\n  {\r\n    id: 'quest_social_01',\r\n    subjectId: 'social_studies',\r\n    title: 'Echoes of the Commonwealth',\r\n    realm: SUBJECTS.SOCIAL_STUDIES.realm,\r\n    color: SUBJECTS.SOCIAL_STUDIES.color,\r\n    description: 'Uncover ancient historical decrees inside the Chrono Archives.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 140,\r\n    rewardGold: 30,\r\n  },\r\n  {\r\n    id: 'quest_lang_01',\r\n    subjectId: 'language_arts',\r\n    title: 'The Whispering Tomes',\r\n    realm: SUBJECTS.LANGUAGE_ARTS.realm,\r\n    color: SUBJECTS.LANGUAGE_ARTS.color,\r\n    description: 'Restore missing allegorical stanzas to the Great Library.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 130,\r\n    rewardGold: 20,\r\n  },\r\n  {\r\n    id: 'quest_arts_01',\r\n    subjectId: 'arts_humanities',\r\n    title: 'Harmony of the Spheres',\r\n    realm: SUBJECTS.ARTS_HUMANITIES.realm,\r\n    color: SUBJECTS.ARTS_HUMANITIES.color,\r\n    description: 'Tune the resonant crystal bells in the Gallery of Wonders.',\r\n    status: 'available',\r\n    progress: 'Not Started',\r\n    rewardXp: 160,\r\n    rewardGold: 35,\r\n  },\r\n];\r\n\r\n/**\r\n * Initial Starter Inventory items with procedural icon types and stats.\r\n */\r\nconst STARTER_INVENTORY = [\r\n  {\r\n    id: 'item_compass',\r\n    name: \"Scholar's Compass\",\r\n    type: 'gear',\r\n    slot: 'relic',\r\n    subject: 'General',\r\n    color: PALETTE.GOLD,\r\n    icon: 'compass',\r\n    description: 'Points toward undiscovered knowledge nodes across Kentucky.',\r\n    equipped: true,\r\n  },\r\n  {\r\n    id: 'item_quill',\r\n    name: 'Novice Quill',\r\n    type: 'gear',\r\n    slot: 'weapon',\r\n    subject: 'Language Arts',\r\n    color: PALETTE.LANGUAGE_ARTS,\r\n    icon: 'quill',\r\n    description: 'Inscribes answers swiftly during speed buzzer rounds.',\r\n    equipped: true,\r\n  },\r\n  {\r\n    id: 'item_scroll',\r\n    name: 'Parchment Scroll',\r\n    type: 'consumable',\r\n    slot: null,\r\n    subject: 'Social Studies',\r\n    color: PALETTE.PARCHMENT_BORDER,\r\n    icon: 'scroll',\r\n    description: 'Reveals one historical hint during an encounter.',\r\n    equipped: false,\r\n    quantity: 2,\r\n  },\r\n  {\r\n    id: 'item_flask',\r\n    name: 'Elixir of Focus',\r\n    type: 'consumable',\r\n    slot: null,\r\n    subject: 'Science',\r\n    color: PALETTE.SCIENCE,\r\n    icon: 'flask',\r\n    description: 'Restores 25 Energy points when facing challenging questions.',\r\n    equipped: false,\r\n    quantity: 3,\r\n  },\r\n  {\r\n    id: 'item_sigil',\r\n    name: \"Governor's Sigil\",\r\n    type: 'artifact',\r\n    slot: null,\r\n    subject: 'General',\r\n    color: PALETTE.BORDER_FOCUS,\r\n    icon: 'sigil',\r\n    description: 'Mark of an official contender for the Governor\\'s Cup.',\r\n    equipped: false,\r\n    quantity: 1,\r\n  },\r\n];\r\n\r\n/**\r\n * Creates a pristine default player profile.\r\n * Stored locally in localStorage for 100% guest-first playability.\r\n * @returns {object}\r\n */\r\nfunction createDefaultPlayerProfile() {\r\n  return {\r\n    handle: generateAdventurerHandle(),\r\n    gradeBand: '6-8',\r\n    level: 1,\r\n    hp: 100,\r\n    maxHp: 100,\r\n    xp: 0,\r\n    maxXp: 100,\r\n    gold: 50,\r\n    activeRealm: 'Cipher Caverns',\r\n    inventory: STARTER_INVENTORY.map(item => ({ ...item })),\r\n    quests: STARTER_QUESTS.map(q => ({ ...q })),\r\n    settings: {\r\n      audioMuted: false,\r\n      reducedMotion: false,\r\n      highContrast: false,\r\n    },\r\n  };\r\n}\n\n/* --- SYNTHETIC QUESTIONS & ENCOUNTERS --- */\n\n// src/data/questions.js — Synthetic Curriculum Questions & Dungeon Encounter Data\r\n// Aligned with KAAC Middle Grades (Grades 6–8) Curriculum.\r\n// 100% Synthetic, original test items with complete provenance metadata.\r\n\r\n\r\nconst SYNTHETIC_QUESTIONS = [\r\n  // --- SCIENCE (Verdant Wilds) ---\r\n  {\r\n    id: 'syn_sci_001',\r\n    subject: SUBJECTS.SCIENCE.id,\r\n    conceptIds: ['science.ecosystems.photosynthesis'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'During photosynthesis in plant cells, which organelle captures radiant light energy to synthesize glucose?',\r\n    choices: [\r\n      { id: 'a', text: 'Mitochondrion' },\r\n      { id: 'b', text: 'Chloroplast' },\r\n      { id: 'c', text: 'Ribosome' },\r\n      { id: 'd', text: 'Endoplasmic reticulum' },\r\n    ],\r\n    answerKey: 'b',\r\n    explanation: 'Chloroplasts contain chlorophyll, the green pigment that absorbs sunlight to drive photosynthesis.',\r\n    difficulty: 1,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n  {\r\n    id: 'syn_sci_002',\r\n    subject: SUBJECTS.SCIENCE.id,\r\n    conceptIds: ['science.physics.newton-laws'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: \"According to Newton's First Law of Motion, an object in motion will remain in motion unless acted upon by what?\",\r\n    choices: [\r\n      { id: 'a', text: 'An unbalanced external force' },\r\n      { id: 'b', text: 'A magnetic field' },\r\n      { id: 'c', text: 'A constant velocity' },\r\n      { id: 'd', text: 'A change in thermal energy' },\r\n    ],\r\n    answerKey: 'a',\r\n    explanation: \"Newton's First Law (Law of Inertia) states an object maintains uniform velocity unless an unbalanced external force acts upon it.\",\r\n    difficulty: 2,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n  {\r\n    id: 'syn_sci_003',\r\n    subject: SUBJECTS.SCIENCE.id,\r\n    conceptIds: ['science.earth.karst-geology'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'Kentucky contains Mammoth Cave, the longest known cave system in the world. What type of soluble rock topography formed this landscape?',\r\n    choices: [\r\n      { id: 'a', text: 'Basaltic plateau' },\r\n      { id: 'b', text: 'Karst limestone' },\r\n      { id: 'c', text: 'Granite pluton' },\r\n      { id: 'd', text: 'Volcanic tuff' },\r\n    ],\r\n    answerKey: 'b',\r\n    explanation: 'Karst topography develops when acidic groundwater dissolves soluble bedrock such as limestone, forming sinkholes and extensive cavern networks.',\r\n    difficulty: 2,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n  {\r\n    id: 'syn_sci_004',\r\n    subject: SUBJECTS.SCIENCE.id,\r\n    conceptIds: ['science.biology.cell-theory'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'Which cellular structure regulates what enters and exits the cell, maintaining homeostasis?',\r\n    choices: [\r\n      { id: 'a', text: 'Cell membrane' },\r\n      { id: 'b', text: 'Nucleolus' },\r\n      { id: 'c', text: 'Vacuole membrane' },\r\n      { id: 'd', text: 'Centriole' },\r\n    ],\r\n    answerKey: 'a',\r\n    explanation: 'The selectively permeable phospholipid bilayer of the cell membrane controls the transport of substances into and out of the cell.',\r\n    difficulty: 1,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n\r\n  // --- MATHEMATICS (Cipher Caverns) ---\r\n  {\r\n    id: 'syn_math_001',\r\n    subject: SUBJECTS.MATH.id,\r\n    conceptIds: ['math.algebra.linear-equations'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'Solve for x in the equation: 3x - 7 = 14.',\r\n    choices: [\r\n      { id: 'a', text: 'x = 5' },\r\n      { id: 'b', text: 'x = 7' },\r\n      { id: 'c', text: 'x = 8' },\r\n      { id: 'd', text: 'x = 21' },\r\n    ],\r\n    answerKey: 'b',\r\n    explanation: 'Add 7 to both sides: 3x = 21. Divide by 3: x = 7.',\r\n    difficulty: 1,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n  {\r\n    id: 'syn_math_002',\r\n    subject: SUBJECTS.MATH.id,\r\n    conceptIds: ['math.number-sense.primes'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'What is the prime factorization of 72?',\r\n    choices: [\r\n      { id: 'a', text: '2³ × 3²' },\r\n      { id: 'b', text: '2² × 3³' },\r\n      { id: 'c', text: '2⁴ × 3' },\r\n      { id: 'd', text: '8 × 9' },\r\n    ],\r\n    answerKey: 'a',\r\n    explanation: '72 = 8 × 9 = 2³ × 3². (Note that 8 and 9 are not prime numbers themselves).',\r\n    difficulty: 2,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n  {\r\n    id: 'syn_math_003',\r\n    subject: SUBJECTS.MATH.id,\r\n    conceptIds: ['math.geometry.angles'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'If two angles are supplementary and one angle measures 65°, what is the measure of the second angle?',\r\n    choices: [\r\n      { id: 'a', text: '25°' },\r\n      { id: 'b', text: '115°' },\r\n      { id: 'c', text: '125°' },\r\n      { id: 'd', text: '180°' },\r\n    ],\r\n    answerKey: 'b',\r\n    explanation: 'Supplementary angles sum to 180°. 180° - 65° = 115°.',\r\n    difficulty: 1,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n\r\n  // --- SOCIAL STUDIES (Kingdoms of Time) ---\r\n  {\r\n    id: 'syn_ss_001',\r\n    subject: SUBJECTS.SOCIAL_STUDIES.id,\r\n    conceptIds: ['social_studies.ky-history.statehood'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'In 1792, Kentucky was admitted to the Union as which numbered state?',\r\n    choices: [\r\n      { id: 'a', text: '13th' },\r\n      { id: 'b', text: '14th' },\r\n      { id: 'c', text: '15th' },\r\n      { id: 'd', text: '16th' },\r\n    ],\r\n    answerKey: 'c',\r\n    explanation: 'Kentucky was admitted as the 15th state on June 1, 1792, following Vermont (14th).',\r\n    difficulty: 1,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n  {\r\n    id: 'syn_ss_002',\r\n    subject: SUBJECTS.SOCIAL_STUDIES.id,\r\n    conceptIds: ['social_studies.us-history.constitution'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'Which constitutional principle divides government power between national and state governments?',\r\n    choices: [\r\n      { id: 'a', text: 'Federalism' },\r\n      { id: 'b', text: 'Separation of powers' },\r\n      { id: 'c', text: 'Popular sovereignty' },\r\n      { id: 'd', text: 'Judicial review' },\r\n    ],\r\n    answerKey: 'a',\r\n    explanation: 'Federalism is the system of shared power and sovereignty between the central national government and regional state governments.',\r\n    difficulty: 2,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n\r\n  // --- LANGUAGE ARTS (Whispering Archives) ---\r\n  {\r\n    id: 'syn_la_001',\r\n    subject: SUBJECTS.LANGUAGE_ARTS.id,\r\n    conceptIds: ['language_arts.literary-devices.figurative-language'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'Which figure of speech is demonstrated in the line: \"The wind whispered through the hollow pines\"?',\r\n    choices: [\r\n      { id: 'a', text: 'Hyperbole' },\r\n      { id: 'b', text: 'Personification' },\r\n      { id: 'c', text: 'Simile' },\r\n      { id: 'd', text: 'Oxymoron' },\r\n    ],\r\n    answerKey: 'b',\r\n    explanation: 'Personification gives human characteristics, such as whispering, to non-human elements like wind.',\r\n    difficulty: 1,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n  {\r\n    id: 'syn_la_002',\r\n    subject: SUBJECTS.LANGUAGE_ARTS.id,\r\n    conceptIds: ['language_arts.literature.animal-farm'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'In George Orwell\\'s novella \"Animal Farm\", what literary genre uses anthropomorphic animals to represent human political history?',\r\n    choices: [\r\n      { id: 'a', text: 'Allegory' },\r\n      { id: 'b', text: 'Sonnet' },\r\n      { id: 'c', text: 'Memoir' },\r\n      { id: 'd', text: 'Epistle' },\r\n    ],\r\n    answerKey: 'a',\r\n    explanation: 'An allegory is a narrative with a secondary symbolic meaning beyond the literal storyline; Animal Farm allegorizes the Russian Revolution.',\r\n    difficulty: 2,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n\r\n  // --- ARTS & HUMANITIES (Gallery of Wonders) ---\r\n  {\r\n    id: 'syn_arts_001',\r\n    subject: SUBJECTS.ARTS_HUMANITIES.id,\r\n    conceptIds: ['arts_humanities.music.orchestral-families'],\r\n    gradeBand: TARGET_GRADE_BAND,\r\n    prompt: 'To which orchestral instrument family does the clarinet belong?',\r\n    choices: [\r\n      { id: 'a', text: 'Brass' },\r\n      { id: 'b', text: 'Woodwinds' },\r\n      { id: 'c', text: 'Strings' },\r\n      { id: 'd', text: 'Percussion' },\r\n    ],\r\n    answerKey: 'b',\r\n    explanation: 'The clarinet is a single-reed woodwind instrument, characterized by its cylindrical bore and wooden/composite body.',\r\n    difficulty: 1,\r\n    source: { type: 'synthetic', author: 'QUEST: KY Curriculum Team', license: 'CC-BY-4.0', rightsStatus: 'approved' },\r\n    rightsStatus: 'approved',\r\n    reviewStatus: 'approved',\r\n    active: true,\r\n    version: 1,\r\n  },\r\n];\r\n\r\n/**\r\n * Returns a question sanitized for the client (strips answerKey).\r\n * Follows Answer Key Secrecy rule: client never receives the answer key prior to answer submission.\r\n * @param {object} question\r\n * @returns {object}\r\n */\r\nfunction sanitizeQuestionForClient(question) {\r\n  if (!question) return null;\r\n  const { answerKey, ...clientPayload } = question;\r\n  return clientPayload;\r\n}\r\n\r\n/**\r\n * Dungeon encounter sequence definitions for the single-player vertical slice.\r\n * Dungeon: \"The Verdant Sanctuary\" in the Verdant Wilds.\r\n */\r\nconst DUNGEON_ENCOUNTERS = [\r\n  {\r\n    index: 0,\r\n    id: 'enc_sproutling',\r\n    name: 'Bramble Sproutling',\r\n    subjectId: 'science',\r\n    type: 'basic',\r\n    hp: 1,\r\n    maxHp: 1,\r\n    questionId: 'syn_sci_001',\r\n    introText: 'A mischievous Bramble Sproutling blocks the overgrown trail! Answer correctly to break its thorn shield.',\r\n    defeatText: 'The Sproutling scatters into blooming wildflowers!',\r\n  },\r\n  {\r\n    index: 1,\r\n    id: 'enc_cave_wisp',\r\n    name: 'Cipher Wisp',\r\n    subjectId: 'math',\r\n    type: 'basic',\r\n    hp: 1,\r\n    maxHp: 1,\r\n    questionId: 'syn_math_001',\r\n    introText: 'A glowing Cipher Wisp flits around an ancient pressure plate. Solve its equation to align the stones.',\r\n    defeatText: 'The Wisp chimes in harmony and opens the ancient chamber gate!',\r\n  },\r\n  {\r\n    index: 2,\r\n    id: 'enc_chrono_sentry',\r\n    name: 'Pioneer Sentry',\r\n    subjectId: 'social_studies',\r\n    type: 'elite',\r\n    hp: 1,\r\n    maxHp: 1,\r\n    questionId: 'syn_ss_001',\r\n    introText: 'A spectral Pioneer Sentry stands guard before the inner sanctum, testing your Commonwealth knowledge.',\r\n    defeatText: 'The Sentry salutes your academic prowess and steps aside!',\r\n  },\r\n  {\r\n    index: 3,\r\n    id: 'enc_word_specter',\r\n    name: 'Archival Specter',\r\n    subjectId: 'language_arts',\r\n    type: 'elite',\r\n    hp: 1,\r\n    maxHp: 1,\r\n    questionId: 'syn_la_001',\r\n    introText: 'An Archival Specter rustles through fallen parchment, challenging your command of literary devices.',\r\n    defeatText: 'The Specter leaves behind a glowing illuminated manuscript rune!',\r\n  },\r\n  {\r\n    index: 4,\r\n    id: 'enc_boss_guardian',\r\n    name: 'Overgrown Guardian (Boss)',\r\n    subjectId: 'science',\r\n    type: 'boss',\r\n    hp: 2, // Requires 2 successful questions to fell the boss\r\n    maxHp: 2,\r\n    questionIds: ['syn_sci_003', 'syn_sci_002'],\r\n    introText: 'The legendary Overgrown Guardian awakens, covered in Kentucky limestone runes and mossy armor!',\r\n    defeatText: 'The Overgrown Guardian bows deeply, restoring balance to the Verdant Wilds! The Quest is Complete!',\r\n  },\r\n];\n\n/* --- QUESTION SCHEMA & VALIDATION --- */\n\n// src/data/question-schema.js — Question Schema, Rights Gate & Validation Workflow\r\n// Specification: Governor's Cup Middle Grades (Grades 6–8) Curriculum.\r\n// Mandate: Strict rights gating, provenance tracking, duplicate detection, and answer secrecy.\r\n\r\n\r\nconst VALID_RIGHTS_STATUSES = ['approved', 'pending', 'rejected', 'in_review'];\r\nconst VALID_REVIEW_STATUSES = ['draft', 'in_review', 'verified', 'approved', 'rejected', 'retired'];\r\nconst VALID_PROVENANCE_TYPES = ['original', 'synthetic', 'authorized', 'public_domain'];\r\nconst VALID_GRADE_BANDS = [TARGET_GRADE_BAND, '4-5', '6'];\r\n\r\nconst VALID_SUBJECT_IDS = new Set(Object.values(SUBJECTS).map((s) => s.id));\r\n\r\n/**\r\n * Normalizes text for comparison and duplicate detection.\r\n * Removes punctuation, normalizes whitespace, and converts to lowercase.\r\n * @param {string} text\r\n * @returns {string}\r\n */\r\nfunction normalizeText(text) {\r\n  if (typeof text !== 'string') return '';\r\n  return text\r\n    .toLowerCase()\r\n    .replace(/[^\\w\\s]/g, '')\r\n    .replace(/\\s+/g, ' ')\r\n    .trim();\r\n}\r\n\r\n/**\r\n * Calculates token-level Jaccard similarity between two texts.\r\n * Used as a duplicate detection review aid.\r\n * @param {string} textA\r\n * @param {string} textB\r\n * @returns {number} Value between 0.0 and 1.0\r\n */\r\nfunction computeSimilarity(textA, textB) {\r\n  const normA = normalizeText(textA);\r\n  const normB = normalizeText(textB);\r\n  if (!normA || !normB) return 0;\r\n  if (normA === normB) return 1;\r\n\r\n  const tokensA = new Set(normA.split(' '));\r\n  const tokensB = new Set(normB.split(' '));\r\n\r\n  let intersection = 0;\r\n  for (const token of tokensA) {\r\n    if (tokensB.has(token)) intersection++;\r\n  }\r\n\r\n  const union = new Set([...tokensA, ...tokensB]).size;\r\n  return union === 0 ? 0 : intersection / union;\r\n}\r\n\r\n/**\r\n * Validates a single question object against the Governor's Cup Question Schema and Rights Gate.\r\n * @param {object} q Question object to validate\r\n * @returns {{ valid: boolean, errors: string[], rightsStatus: string }}\r\n */\r\nfunction validateQuestion(q) {\r\n  const errors = [];\r\n  if (!q || typeof q !== 'object') {\r\n    return { valid: false, errors: ['Question must be a non-null object'], rightsStatus: 'rejected' };\r\n  }\r\n\r\n  // 1. Stable ID\r\n  if (!q.id || typeof q.id !== 'string' || !/^[a-zA-Z0-9_-]{3,64}$/.test(q.id)) {\r\n    errors.push('id must be an alphanumeric string (3-64 chars, including _ and -)');\r\n  }\r\n\r\n  // 2. Subject Area\r\n  if (!q.subject || !VALID_SUBJECT_IDS.has(q.subject)) {\r\n    errors.push(`subject must be one of: ${Array.from(VALID_SUBJECT_IDS).join(', ')}`);\r\n  }\r\n\r\n  // 3. Concept IDs\r\n  if (!Array.isArray(q.conceptIds) || q.conceptIds.length === 0 || !q.conceptIds.every((c) => typeof c === 'string' && c.length > 0)) {\r\n    errors.push('conceptIds must be a non-empty array of concept strings');\r\n  }\r\n\r\n  // 4. Grade Band\r\n  if (!q.gradeBand || !VALID_GRADE_BANDS.includes(q.gradeBand)) {\r\n    errors.push(`gradeBand must be one of: ${VALID_GRADE_BANDS.join(', ')}`);\r\n  }\r\n\r\n  // 5. Question Prompt\r\n  if (!q.prompt || typeof q.prompt !== 'string' || q.prompt.trim().length < 10) {\r\n    errors.push('prompt must be a string with at least 10 characters');\r\n  }\r\n\r\n  // 6. Choice IDs and Text\r\n  if (!Array.isArray(q.choices) || q.choices.length < 2) {\r\n    errors.push('choices must be an array of at least 2 choice objects');\r\n  } else {\r\n    const choiceIds = new Set();\r\n    for (let i = 0; i < q.choices.length; i++) {\r\n      const choice = q.choices[i];\r\n      if (!choice || typeof choice !== 'object') {\r\n        errors.push(`choices[${i}] must be an object`);\r\n        continue;\r\n      }\r\n      if (!choice.id || typeof choice.id !== 'string') {\r\n        errors.push(`choices[${i}].id must be a non-empty string`);\r\n      } else if (choiceIds.has(choice.id)) {\r\n        errors.push(`Duplicate choice id '${choice.id}' found`);\r\n      } else {\r\n        choiceIds.add(choice.id);\r\n      }\r\n      if (!choice.text || typeof choice.text !== 'string' || choice.text.trim().length === 0) {\r\n        errors.push(`choices[${i}].text must be a non-empty string`);\r\n      }\r\n    }\r\n\r\n    // 7. Answer Key Integrity\r\n    if (!q.answerKey || typeof q.answerKey !== 'string') {\r\n      errors.push('answerKey must be specified as a choice ID string');\r\n    } else if (!choiceIds.has(q.answerKey)) {\r\n      errors.push(`answerKey '${q.answerKey}' does not match any valid choice id`);\r\n    }\r\n  }\r\n\r\n  // 8. Explanation\r\n  if (!q.explanation || typeof q.explanation !== 'string' || q.explanation.trim().length < 5) {\r\n    errors.push('explanation must be a descriptive string (minimum 5 characters)');\r\n  }\r\n\r\n  // 9. Difficulty\r\n  if (typeof q.difficulty !== 'number' || !Number.isInteger(q.difficulty) || q.difficulty < 1 || q.difficulty > 5) {\r\n    errors.push('difficulty must be an integer between 1 and 5');\r\n  }\r\n\r\n  // 10. Source & Provenance\r\n  const source = q.source || q.provenance;\r\n  if (!source || typeof source !== 'object') {\r\n    errors.push('source or provenance object is required to verify item rights and origins');\r\n  } else {\r\n    if (!source.type || !VALID_PROVENANCE_TYPES.includes(source.type)) {\r\n      errors.push(`source.type must be one of: ${VALID_PROVENANCE_TYPES.join(', ')}`);\r\n    }\r\n    const hasRef = Boolean(source.author || source.reference || source.curriculumReference);\r\n    if (!hasRef) {\r\n      errors.push('source must identify an author, reference, or curriculumReference');\r\n    }\r\n  }\r\n\r\n  // 11. Rights Status & Rights Gate\r\n  const rightsStatus = q.rightsStatus || (source && source.rightsStatus) || 'pending';\r\n  if (!VALID_RIGHTS_STATUSES.includes(rightsStatus)) {\r\n    errors.push(`rightsStatus must be one of: ${VALID_RIGHTS_STATUSES.join(', ')}`);\r\n  }\r\n\r\n  // 12. Reviewer Status\r\n  const reviewStatus = q.reviewStatus || q.reviewerStatus || 'draft';\r\n  if (!VALID_REVIEW_STATUSES.includes(reviewStatus)) {\r\n    errors.push(`reviewStatus must be one of: ${VALID_REVIEW_STATUSES.join(', ')}`);\r\n  }\r\n\r\n  // 13. Version\r\n  if (q.version !== undefined && (typeof q.version !== 'number' || !Number.isInteger(q.version) || q.version < 1)) {\r\n    errors.push('version must be a positive integer >= 1');\r\n  }\r\n\r\n  // 14. Active Status & Rights Gate Enforcement\r\n  const active = q.active !== undefined ? Boolean(q.active) : false;\r\n  if (active && rightsStatus !== 'approved') {\r\n    errors.push(`Rights Gate Violation: Question cannot be active when rightsStatus is '${rightsStatus}'. Only 'approved' items may be active.`);\r\n  }\r\n\r\n  return {\r\n    valid: errors.length === 0,\r\n    errors,\r\n    rightsStatus,\r\n  };\r\n}\r\n\r\n/**\r\n * Duplicate detection review aid. Checks a question against existing items in a catalog.\r\n * @param {object} question Target question\r\n * @param {Array<object>} catalog Existing catalog of questions\r\n * @param {number} threshold Similarity threshold (default: 0.75)\r\n * @returns {{ isDuplicateId: boolean, warnings: Array<{ matchedQuestionId: string, similarity: number, reason: string }> }}\r\n */\r\nfunction detectDuplicates(question, catalog = [], threshold = 0.75) {\r\n  const warnings = [];\r\n  let isDuplicateId = false;\r\n\r\n  for (const existing of catalog) {\r\n    if (!existing) continue;\r\n\r\n    // Check duplicate ID\r\n    if (existing.id === question.id) {\r\n      isDuplicateId = true;\r\n      continue;\r\n    }\r\n\r\n    // Exact or near-duplicate prompt check\r\n    const similarity = computeSimilarity(question.prompt || '', existing.prompt || '');\r\n    if (similarity >= 1.0) {\r\n      warnings.push({\r\n        matchedQuestionId: existing.id,\r\n        similarity: 1.0,\r\n        reason: 'Identical normalized prompt detected',\r\n      });\r\n    } else if (similarity >= threshold) {\r\n      warnings.push({\r\n        matchedQuestionId: existing.id,\r\n        similarity: Math.round(similarity * 100) / 100,\r\n        reason: `High semantic prompt similarity (${Math.round(similarity * 100)}%) with ${existing.id}`,\r\n      });\r\n    }\r\n  }\r\n\r\n  return { isDuplicateId, warnings };\r\n}\r\n\r\n/**\r\n * Validates and imports a batch of questions through the staging and rights gate pipeline.\r\n * @param {Array<object>} batch Array of candidate question objects\r\n * @param {Array<object>} existingCatalog Array of already active/staged questions\r\n * @returns {{ success: boolean, imported: Array<object>, rejected: Array<{ question: object, errors: string[] }>, warnings: Array<{ questionId: string, warnings: any[] }> }}\r\n */\r\nfunction importQuestions(batch, existingCatalog = []) {\r\n  if (!Array.isArray(batch)) {\r\n    return {\r\n      success: false,\r\n      imported: [],\r\n      rejected: [{ question: batch, errors: ['Batch must be an array of questions'] }],\r\n      warnings: [],\r\n    };\r\n  }\r\n\r\n  const imported = [];\r\n  const rejected = [];\r\n  const warnings = [];\r\n  const workingCatalog = [...existingCatalog];\r\n  const seenBatchIds = new Set();\r\n\r\n  for (const item of batch) {\r\n    if (!item || typeof item !== 'object') {\r\n      rejected.push({ question: item, errors: ['Question entry must be an object'] });\r\n      continue;\r\n    }\r\n\r\n    // Duplicate ID in current batch\r\n    if (seenBatchIds.has(item.id)) {\r\n      rejected.push({\r\n        question: item,\r\n        errors: [`Duplicate question ID '${item.id}' detected within current import batch`],\r\n      });\r\n      continue;\r\n    }\r\n    seenBatchIds.add(item.id);\r\n\r\n    // Schema and Rights Gate Validation\r\n    const validation = validateQuestion(item);\r\n    if (!validation.valid) {\r\n      rejected.push({ question: item, errors: validation.errors });\r\n      continue;\r\n    }\r\n\r\n    // Duplicate Detection against working catalog\r\n    const dupCheck = detectDuplicates(item, workingCatalog);\r\n    if (dupCheck.isDuplicateId) {\r\n      rejected.push({\r\n        question: item,\r\n        errors: [`Duplicate question ID '${item.id}' already exists in active question catalog`],\r\n      });\r\n      continue;\r\n    }\r\n\r\n    if (dupCheck.warnings.length > 0) {\r\n      warnings.push({\r\n        questionId: item.id,\r\n        warnings: dupCheck.warnings,\r\n      });\r\n    }\r\n\r\n    // Item passed validation and rights gate\r\n    const normalized = {\r\n      ...item,\r\n      rightsStatus: item.rightsStatus || (item.source && item.source.rightsStatus) || 'approved',\r\n      reviewStatus: item.reviewStatus || 'approved',\r\n      version: item.version || 1,\r\n      active: item.active !== undefined ? Boolean(item.active) : true,\r\n    };\r\n\r\n    imported.push(normalized);\r\n    workingCatalog.push(normalized);\r\n  }\r\n\r\n  return {\r\n    success: rejected.length === 0,\r\n    imported,\r\n    rejected,\r\n    warnings,\r\n  };\r\n}\r\n\r\n/**\r\n * Transitions a question's rights status through the human review pipeline.\r\n * Enforces that retiring or revoking rights automatically revokes active serving status.\r\n * @param {object} question Target question\r\n * @param {string} newRightsStatus 'approved' | 'pending' | 'rejected' | 'in_review'\r\n * @param {string} reviewerHandle Pseudonymous reviewer identifier\r\n * @returns {object} Updated question record\r\n */\r\nfunction updateQuestionRights(question, newRightsStatus, reviewerHandle = 'Reviewer') {\r\n  if (!VALID_RIGHTS_STATUSES.includes(newRightsStatus)) {\r\n    throw new Error(`Invalid rights status '${newRightsStatus}'. Allowed: ${VALID_RIGHTS_STATUSES.join(', ')}`);\r\n  }\r\n\r\n  const updated = {\r\n    ...question,\r\n    rightsStatus: newRightsStatus,\r\n    version: (question.version || 1) + 1,\r\n    reviewerNotes: `Rights status updated to '${newRightsStatus}' by ${reviewerHandle} on ${new Date().toISOString()}`,\r\n  };\r\n\r\n  if (newRightsStatus !== 'approved') {\r\n    updated.active = false;\r\n  }\r\n\r\n  return updated;\r\n}\n\n/* --- SPACED REPETITION ENGINE --- */\n\nconst DAY_MS = 86_400_000;\nconst INTERVALS = SPACED_REPETITION.INTERVALS_DAYS;\nconst REQUIRED_DISTINCT_QUESTIONS = SPACED_REPETITION.VERIFICATION_MIN_COUNT;\n\n/**\n * Creates a blank concept mastery record.\n * @param {string} userId\n * @param {string} conceptId\n * @param {number} [now=Date.now()]\n * @returns {object}\n */\nfunction createInitialMasteryRecord(userId, conceptId, now = Date.now()) {\n  return {\n    userId,\n    conceptId,\n    stage: 0,\n    intervalDays: INTERVALS[0],\n    dueAt: now,\n    consecutiveCorrect: 0,\n    distinctQuestionsCorrect: [],\n    isMastered: false,\n    lastAttemptAt: 0,\n  };\n}\n\n/**\n * Calculates the next spaced review schedule and mastery status based on an attempt.\n *\n * Rules:\n * 1. Unassisted Correct: Advances interval stage (1 -> 3 -> 7 -> 14 -> 30 days).\n * 2. Assisted Correct: Awards credit for the session but DOES NOT advance mastery stage.\n * 3. Incorrect: Resets interval stage to 1 day and resets consecutive counter.\n * 4. Multi-Question Verification: Mastery requires at least 3 distinct questions answered correctly\n *    and reaching the top interval tier (30 days).\n *\n * @param {object} currentRecord Current concept mastery record (or null for new)\n * @param {object} attempt { isCorrect: boolean, assisted: boolean, questionId: string }\n * @param {number} [now=Date.now()]\n * @returns {object} Updated mastery record\n */\nfunction calculateNextReview(currentRecord, attempt, now = Date.now()) {\n  const base = currentRecord ? { ...currentRecord } : createInitialMasteryRecord('', '', now);\n  const { isCorrect, assisted = false, questionId } = attempt;\n\n  const distinctSet = new Set(base.distinctQuestionsCorrect || []);\n\n  if (isCorrect) {\n    if (questionId) {\n      distinctSet.add(questionId);\n    }\n\n    if (assisted) {\n      // Assisted Correct: Marked assisted; do NOT advance mastery stage or interval\n      base.lastAttemptAt = now;\n      base.dueAt = now + base.intervalDays * DAY_MS;\n      base.distinctQuestionsCorrect = Array.from(distinctSet);\n      return base;\n    }\n\n    // Unassisted Correct: Advance to next spaced repetition interval tier\n    const nextStage = Math.min(base.stage + 1, INTERVALS.length);\n    const intervalDays = nextStage < INTERVALS.length\n      ? INTERVALS[nextStage]\n      : INTERVALS[INTERVALS.length - 1];\n\n    const consecutive = (base.consecutiveCorrect || 0) + 1;\n    const isMastered = distinctSet.size >= REQUIRED_DISTINCT_QUESTIONS && nextStage >= INTERVALS.length - 1;\n\n    base.stage = nextStage;\n    base.intervalDays = intervalDays;\n    base.dueAt = now + intervalDays * DAY_MS;\n    base.consecutiveCorrect = consecutive;\n    base.distinctQuestionsCorrect = Array.from(distinctSet);\n    base.isMastered = isMastered;\n    base.lastAttemptAt = now;\n  } else {\n    // Incorrect: Reset interval to 1 day and reset consecutive counter\n    base.stage = 0;\n    base.intervalDays = INTERVALS[0];\n    base.dueAt = now + INTERVALS[0] * DAY_MS;\n    base.consecutiveCorrect = 0;\n    base.isMastered = false;\n    base.lastAttemptAt = now;\n    base.distinctQuestionsCorrect = Array.from(distinctSet);\n  }\n\n  return base;\n}\n\n/**\n * Filters and returns concept mastery records that are currently due for spaced review.\n * @param {Array<object>} masteryRecords\n * @param {number} [now=Date.now()]\n * @returns {Array<object>} Records where dueAt <= now\n */\nfunction getDueReviews(masteryRecords = [], now = Date.now()) {\n  if (!Array.isArray(masteryRecords)) return [];\n  return masteryRecords\n    .filter((record) => record && record.dueAt <= now)\n    .sort((a, b) => a.dueAt - b.dueAt);\n}\n\n/**\n * Computes aggregate subject realm progress across curriculum concepts.\n * @param {Array<object>} masteryRecords\n * @param {Array<object>} allQuestions Catalog of active questions\n * @returns {object} Progress summary per subject realm\n */\nfunction computeSubjectProgress(masteryRecords = [], allQuestions = []) {\n  const progress = {};\n  for (const subjectKey of Object.keys(SUBJECTS)) {\n    const sub = SUBJECTS[subjectKey];\n    progress[sub.id] = {\n      subjectId: sub.id,\n      name: sub.name,\n      realm: sub.realm,\n      color: sub.color,\n      totalConceptsEncountered: 0,\n      masteredConcepts: 0,\n      activeReviewsDue: 0,\n    };\n  }\n\n  const conceptToSubject = new Map();\n  for (const q of allQuestions) {\n    if (q && q.subject && Array.isArray(q.conceptIds)) {\n      for (const c of q.conceptIds) {\n        if (!conceptToSubject.has(c)) {\n          conceptToSubject.set(c, q.subject);\n        }\n      }\n    }\n  }\n\n  const now = Date.now();\n  for (const record of masteryRecords) {\n    if (!record) continue;\n    const subjectId = conceptToSubject.get(record.conceptId) || record.subjectId || 'science';\n    if (!progress[subjectId]) continue;\n\n    progress[subjectId].totalConceptsEncountered++;\n    if (record.isMastered) {\n      progress[subjectId].masteredConcepts++;\n    }\n    if (record.dueAt <= now) {\n      progress[subjectId].activeReviewsDue++;\n    }\n  }\n\n  return progress;\n}\n\n/* --- PROCEDURAL SPRITES & ICONS --- */\n\n// src/client/sprites.js — Procedural Pixel Sprites & Vector Icons\r\n// Zero raster assets: All graphics are encoded in pixel matrices or vector formulas.\r\n\r\n\r\n/**\r\n * 8x8 Procedural Hero Sprites by Direction.\r\n * Palette indices:\r\n * 0 = transparent\r\n * 1 = skin (#FEF3C7)\r\n * 2 = cloak / tunic (#2563EB)\r\n * 3 = boots / belt / eyes (#0F172A)\r\n * 4 = gold trim (#FBBF24)\r\n * 5 = highlight / hair (#D97706)\r\n */\r\nconst HERO_SPRITES = {\r\n  down: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '05555550',\r\n      '55111155',\r\n      '51311315',\r\n      '01111110',\r\n      '02244220',\r\n      '22244222',\r\n      '02333320',\r\n      '03000030',\r\n    ],\r\n  },\r\n  up: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '05555550',\r\n      '55555555',\r\n      '55555555',\r\n      '01111110',\r\n      '02244220',\r\n      '22244222',\r\n      '02333320',\r\n      '03000030',\r\n    ],\r\n  },\r\n  left: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '05555500',\r\n      '55111500',\r\n      '51311500',\r\n      '01111000',\r\n      '02242200',\r\n      '02242220',\r\n      '02333000',\r\n      '00303000',\r\n    ],\r\n  },\r\n  right: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.MATH, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.SOCIAL_STUDIES],\r\n    matrix: [\r\n      '00555550',\r\n      '00511155',\r\n      '00511315',\r\n      '00011110',\r\n      '00224220',\r\n      '02224220',\r\n      '00033320',\r\n      '00030300',\r\n    ],\r\n  },\r\n};\r\n\r\n/**\r\n * 8x8 Procedural NPC Sprites (Elder Sage in Hub).\r\n */\r\nconst NPC_SPRITES = {\r\n  sage: {\r\n    palette: ['transparent', PALETTE.PARCHMENT, PALETTE.BORDER_FOCUS, PALETTE.BG_DARK, PALETTE.GOLD, PALETTE.TEXT_SECONDARY],\r\n    matrix: [\r\n      '05555550',\r\n      '55111155',\r\n      '51311315',\r\n      '01555510',\r\n      '02244220',\r\n      '22244222',\r\n      '02222220',\r\n      '03300330',\r\n    ],\r\n  },\r\n};\r\n\r\n/**\r\n * 8x8 Procedural Dungeon Enemy Sprites.\r\n */\r\nconst ENEMY_SPRITES = {\r\n  // Bramble Sproutling (Science - Verdant Wilds)\r\n  sproutling: {\r\n    palette: ['transparent', PALETTE.SCIENCE, PALETTE.SUCCESS, PALETTE.PARCHMENT, PALETTE.BG_DARK],\r\n    matrix: [\r\n      '00200200',\r\n      '01211210',\r\n      '01111110',\r\n      '11411411',\r\n      '11133111',\r\n      '01111110',\r\n      '00100100',\r\n      '01000010',\r\n    ],\r\n  },\r\n  // Cipher Wisp (Math - Cipher Caverns)\r\n  wisp: {\r\n    palette: ['transparent', PALETTE.MATH, PALETTE.BORDER_FOCUS, PALETTE.GOLD, PALETTE.TEXT_PRIMARY],\r\n    matrix: [\r\n      '00022000',\r\n      '00244200',\r\n      '02433420',\r\n      '24311342',\r\n      '24311342',\r\n      '02433420',\r\n      '00244200',\r\n      '00022000',\r\n    ],\r\n  },\r\n  // Pioneer Sentry (Social Studies - Chrono Archives)\r\n  sentry: {\r\n    palette: ['transparent', PALETTE.SOCIAL_STUDIES, PALETTE.PARCHMENT, PALETTE.BG_DARK, PALETTE.SURFACE_ELEVATED],\r\n    matrix: [\r\n      '01111110',\r\n      '01111110',\r\n      '02322320',\r\n      '00222200',\r\n      '04411440',\r\n      '44411444',\r\n      '04444440',\r\n      '03000030',\r\n    ],\r\n  },\r\n  // Archival Specter (Language Arts - Whispering Archives)\r\n  specter: {\r\n    palette: ['transparent', PALETTE.LANGUAGE_ARTS, PALETTE.PARCHMENT, PALETTE.TEXT_PRIMARY, PALETTE.BG_DARK],\r\n    matrix: [\r\n      '00111100',\r\n      '01111110',\r\n      '11411411',\r\n      '11111111',\r\n      '01222210',\r\n      '01222210',\r\n      '10100101',\r\n      '10000001',\r\n    ],\r\n  },\r\n  // Overgrown Guardian (Science Boss - Verdant Wilds)\r\n  boss: {\r\n    palette: ['transparent', PALETTE.SCIENCE, PALETTE.SURFACE_ELEVATED, PALETTE.GOLD, PALETTE.PARCHMENT, PALETTE.SUCCESS, PALETTE.BORDER_FOCUS],\r\n    matrix: [\r\n      '00155100',\r\n      '01222210',\r\n      '12644621',\r\n      '12244221',\r\n      '01222210',\r\n      '13111131',\r\n      '13155131',\r\n      '01100110',\r\n    ],\r\n  },\r\n};\r\n\r\n/**\r\n * Draws a procedural pixel matrix sprite onto a canvas 2D context.\r\n * @param {CanvasRenderingContext2D} ctx\r\n * @param {object} sprite\r\n * @param {number} destX\r\n * @param {number} destY\r\n * @param {number} [pixelScale=2]\r\n */\r\nfunction renderPixelSprite(ctx, sprite, destX, destY, pixelScale = 2) {\r\n  if (!ctx || !sprite || !sprite.matrix) return;\r\n  for (let row = 0; row < sprite.matrix.length; row++) {\r\n    const line = sprite.matrix[row];\r\n    for (let col = 0; col < line.length; col++) {\r\n      const colorIndex = parseInt(line[col], 10);\r\n      if (colorIndex > 0 && sprite.palette[colorIndex]) {\r\n        ctx.fillStyle = sprite.palette[colorIndex];\r\n        ctx.fillRect(\r\n          Math.floor(destX + col * pixelScale),\r\n          Math.floor(destY + row * pixelScale),\r\n          pixelScale,\r\n          pixelScale\r\n        );\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n/**\r\n * Generates an offscreen Canvas texture atlas containing 16x16 procedural terrain tiles.\r\n * Caches grass, paths, water, trees, dungeon bricks, and portal tiles.\r\n * @returns {HTMLCanvasElement|null}\r\n */\r\nfunction createTileAtlas() {\r\n  if (typeof document === 'undefined') return null;\r\n\r\n  const atlas = document.createElement('canvas');\r\n  atlas.width = 160;\r\n  atlas.height = 128;\r\n  const ctx = atlas.getContext('2d');\r\n  if (!ctx) return null;\r\n\r\n  // 1. Grass Tile (Index 0: 0, 0)\r\n  ctx.fillStyle = '#065F46'; // Dark Emerald base\r\n  ctx.fillRect(0, 0, 16, 16);\r\n  ctx.fillStyle = '#059669'; // Emerald highlights\r\n  ctx.fillRect(2, 2, 2, 4);\r\n  ctx.fillRect(10, 3, 2, 5);\r\n  ctx.fillRect(6, 9, 2, 4);\r\n  ctx.fillRect(12, 11, 2, 3);\r\n  ctx.fillStyle = '#10B981'; // Bright tip\r\n  ctx.fillRect(2, 2, 2, 1);\r\n  ctx.fillRect(10, 3, 2, 1);\r\n  ctx.fillRect(6, 9, 2, 1);\r\n\r\n  // 2. Cobblestone Path Tile (Index 1: 16, 0)\r\n  ctx.fillStyle = '#334155'; // Slate 700 mortar\r\n  ctx.fillRect(16, 0, 16, 16);\r\n  ctx.fillStyle = '#475569'; // Slate 600 stone\r\n  ctx.fillRect(17, 1, 6, 6);\r\n  ctx.fillRect(25, 2, 6, 5);\r\n  ctx.fillRect(18, 9, 6, 6);\r\n  ctx.fillRect(26, 8, 5, 7);\r\n  ctx.fillStyle = '#64748B'; // Slate 500 edge highlight\r\n  ctx.fillRect(17, 1, 6, 1);\r\n  ctx.fillRect(25, 2, 6, 1);\r\n  ctx.fillRect(18, 9, 6, 1);\r\n\r\n  // 3. Water Tile (Index 2: 32, 0)\r\n  ctx.fillStyle = '#1E3A8A'; // Blue 900 base\r\n  ctx.fillRect(32, 0, 16, 16);\r\n  ctx.fillStyle = '#2563EB'; // Blue 600 wave\r\n  ctx.fillRect(34, 4, 8, 2);\r\n  ctx.fillRect(38, 10, 8, 2);\r\n  ctx.fillStyle = '#38BDF8'; // Sky 400 sparkle\r\n  ctx.fillRect(36, 4, 2, 1);\r\n  ctx.fillRect(42, 10, 2, 1);\r\n\r\n  // 4. Stone Wall / Dungeon Brick (Index 3: 48, 0)\r\n  ctx.fillStyle = '#0F172A'; // Slate 900 mortar\r\n  ctx.fillRect(48, 0, 16, 16);\r\n  ctx.fillStyle = '#1E293B'; // Slate 800 brick\r\n  ctx.fillRect(49, 1, 14, 6);\r\n  ctx.fillRect(49, 9, 14, 6);\r\n  ctx.fillStyle = '#334155'; // Slate 700 top highlight\r\n  ctx.fillRect(49, 1, 14, 1);\r\n  ctx.fillRect(49, 9, 14, 1);\r\n\r\n  // 5. Tree Foliage (Index 4: 64, 0)\r\n  ctx.fillStyle = '#064E3B'; // Deep green shadow\r\n  ctx.fillRect(64, 0, 16, 16);\r\n  ctx.fillStyle = '#059669'; // Emerald canopy\r\n  ctx.fillRect(66, 2, 12, 12);\r\n  ctx.fillStyle = '#10B981'; // Sunlight tip\r\n  ctx.fillRect(68, 4, 4, 4);\r\n\r\n  // 6. Dungeon Stone Floor (Index 5: 80, 0)\r\n  ctx.fillStyle = '#1E293B'; // Slate 800 base\r\n  ctx.fillRect(80, 0, 16, 16);\r\n  ctx.fillStyle = '#334155'; // Slate 700 flagstone lines\r\n  ctx.strokeRect(80.5, 0.5, 15, 15);\r\n  ctx.fillStyle = '#475569';\r\n  ctx.fillRect(83, 3, 2, 2);\r\n  ctx.fillRect(91, 10, 2, 2);\r\n\r\n  // 7. Dungeon Gateway / Arch (Index 6: 96, 0)\r\n  ctx.fillStyle = '#0F172A';\r\n  ctx.fillRect(96, 0, 16, 16);\r\n  ctx.fillStyle = '#38BDF8'; // Sky glow\r\n  ctx.fillRect(99, 2, 10, 14);\r\n  ctx.fillStyle = '#F8FAFC';\r\n  ctx.fillRect(102, 6, 4, 6);\r\n\r\n  return atlas;\r\n}\r\n\r\n/**\r\n * Returns procedural inline SVG strings for UI icons without raster assets.\r\n * @param {string} iconName\r\n * @param {string} [color=PALETTE.TEXT_PRIMARY]\r\n * @param {number} [size=20]\r\n * @returns {string}\r\n */\r\nfunction getSvgIcon(iconName, color = PALETTE.TEXT_PRIMARY, size = 20) {\r\n  const common = `width=\"${size}\" height=\"${size}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"`;\r\n\r\n  switch (iconName) {\r\n    case 'compass':\r\n      return `<svg ${common}><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polygon points=\"16.24 7.76 14.12 14.12 7.76 16.24 9.88 9.88 16.24 7.76\" fill=\"${color}\" fill-opacity=\"0.3\"></polygon></svg>`;\r\n    case 'quill':\r\n      return `<svg ${common}><path d=\"M12 19l7-7 3 3-7 7-3-3z\"></path><path d=\"M18 13l-1.5-7.5L2 2l3.5 14.5L13 18z\"></path><path d=\"M2 2l7.586 7.586\"></path><circle cx=\"11\" cy=\"11\" r=\"2\"></circle></svg>`;\r\n    case 'scroll':\r\n      return `<svg ${common}><path d=\"M19 17h2a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h2\"></path><path d=\"M15 21v-4a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v4a2 2 0 0 0 2 2h9a2 2 0 0 0 2-2z\"></path></svg>`;\r\n    case 'flask':\r\n      return `<svg ${common}><path d=\"M9 3h6\"></path><path d=\"M10 3v5l-4 7a2 2 0 0 0 1.7 3h8.6a2 2 0 0 0 1.7-3l-4-7V3\"></path><path d=\"M8 14h8\"></path></svg>`;\r\n    case 'sigil':\r\n      return `<svg ${common}><path d=\"M12 2l8 4.5v6c0 5-3.5 9.5-8 11-4.5-1.5-8-6-8-11v-6L12 2z\"></path><circle cx=\"12\" cy=\"11\" r=\"3\" fill=\"${color}\" fill-opacity=\"0.4\"></circle></svg>`;\r\n    case 'map':\r\n      return `<svg ${common}><polygon points=\"1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6\"></polygon><line x1=\"8\" y1=\"2\" x2=\"8\" y2=\"18\"></line><line x1=\"16\" y1=\"6\" x2=\"16\" y2=\"22\"></line></svg>`;\r\n    case 'quests':\r\n      return `<svg ${common}><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"></line><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"></line><polyline points=\"10 9 9 9 8 9\"></polyline></svg>`;\r\n    case 'inventory':\r\n      return `<svg ${common}><path d=\"M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z\"></path><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><path d=\"M16 10a4 4 0 0 1-8 0\"></path></svg>`;\r\n    case 'settings':\r\n      return `<svg ${common}><circle cx=\"12\" cy=\"12\" r=\"3\"></circle><path d=\"M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z\"></path></svg>`;\r\n    case 'audio-on':\r\n      return `<svg ${common}><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"></polygon><path d=\"M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07\"></path></svg>`;\r\n    case 'audio-off':\r\n      return `<svg ${common}><polygon points=\"11 5 6 9 2 9 2 15 6 15 11 19 11 5\"></polygon><line x1=\"23\" y1=\"9\" x2=\"17\" y2=\"15\"></line><line x1=\"17\" y1=\"9\" x2=\"23\" y2=\"15\"></line></svg>`;\r\n    case 'sword':\r\n      return `<svg ${common}><polyline points=\"14.5 17.5 3 6 3 3 6 3 17.5 14.5\"></polyline><line x1=\"13\" y1=\"19\" x2=\"19\" y2=\"13\"></line><line x1=\"16\" y1=\"16\" x2=\"20\" y2=\"20\"></line><line x1=\"19\" y1=\"21\" x2=\"21\" y2=\"19\"></line></svg>`;\r\n    case 'shield':\r\n      return `<svg ${common}><path d=\"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z\"></path></svg>`;\r\n    case 'trophy':\r\n      return `<svg ${common}><path d=\"M6 9H4.5a2.5 2.5 0 0 1 0-5H6\"></path><path d=\"M18 9h1.5a2.5 2.5 0 0 0 0-5H18\"></path><path d=\"M4 22h16\"></path><path d=\"M10 14.66V17c0 .55-.45 1-1 1H8c-.55 0-1 .45-1 1v1h10v-1c0-.55-.45-1-1-1h-1c-.55 0-1-.45-1-1v-2.34\"></path><path d=\"M6 4h12v7a6 6 0 0 1-12 0V4z\"></path></svg>`;\r\n    case 'close':\r\n      return `<svg ${common}><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"></line><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"></line></svg>`;\r\n    default:\r\n      return `<svg ${common}><circle cx=\"12\" cy=\"12\" r=\"10\"></circle></svg>`;\r\n  }\r\n}\n\n/* --- PROCEDURAL AUDIO SYNTHESIZER --- */\n\n// src/client/audio.js — Procedural Web Audio FX Synthesizer\r\n// Pure algorithmic sound synthesis with zero external audio assets.\r\n\r\nclass SoundEngine {\r\n  constructor() {\r\n    this.ctx = null;\r\n    this.muted = false;\r\n    this.initialized = false;\r\n  }\r\n\r\n  /**\r\n   * Initializes or resumes the AudioContext on first user gesture.\r\n   */\r\n  init() {\r\n    if (this.ctx) {\r\n      if (this.ctx.state === 'suspended') {\r\n        this.ctx.resume().catch(() => {});\r\n      }\r\n      return;\r\n    }\r\n\r\n    const AudioContextClass = globalThis.AudioContext || globalThis.webkitAudioContext;\r\n    if (AudioContextClass) {\r\n      try {\r\n        this.ctx = new AudioContextClass();\r\n        this.initialized = true;\r\n      } catch {\r\n        // Audio unavailable or blocked\r\n      }\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Toggles sound on or off.\r\n   * @param {boolean} [force]\r\n   * @returns {boolean} current muted state\r\n   */\r\n  toggleMute(force) {\r\n    this.muted = typeof force === 'boolean' ? force : !this.muted;\r\n    return this.muted;\r\n  }\r\n\r\n  isMuted() {\r\n    return this.muted;\r\n  }\r\n\r\n  /**\r\n   * Synthesizes an 8-bit style UI click.\r\n   */\r\n  playClick() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'triangle';\r\n      osc.frequency.setValueAtTime(800, now);\r\n      osc.frequency.exponentialRampToValueAtTime(300, now + 0.04);\r\n\r\n      gain.gain.setValueAtTime(0.15, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.04);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes a friendly 3-note arpeggio chime (C5 - E5 - G5).\r\n   */\r\n  playChime() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const notes = [523.25, 659.25, 783.99]; // C5, E5, G5\r\n      const now = this.ctx.currentTime;\r\n\r\n      notes.forEach((freq, index) => {\r\n        const noteStart = now + index * 0.06;\r\n        const osc = this.ctx.createOscillator();\r\n        const gain = this.ctx.createGain();\r\n\r\n        osc.type = 'sine';\r\n        osc.frequency.setValueAtTime(freq, noteStart);\r\n\r\n        gain.gain.setValueAtTime(0.18, noteStart);\r\n        gain.gain.exponentialRampToValueAtTime(0.001, noteStart + 0.14);\r\n\r\n        osc.connect(gain);\r\n        gain.connect(this.ctx.destination);\r\n\r\n        osc.start(noteStart);\r\n        osc.stop(noteStart + 0.14);\r\n      });\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes a subtle, quiet movement tick.\r\n   */\r\n  playWalk() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'triangle';\r\n      osc.frequency.setValueAtTime(140, now);\r\n      osc.frequency.exponentialRampToValueAtTime(60, now + 0.03);\r\n\r\n      gain.gain.setValueAtTime(0.06, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.03);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes a high modal opening cue.\r\n   */\r\n  playAlert() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'sine';\r\n      osc.frequency.setValueAtTime(440, now);\r\n      osc.frequency.exponentialRampToValueAtTime(880, now + 0.08);\r\n\r\n      gain.gain.setValueAtTime(0.12, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.08);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes encounter start cue (dramatic low-to-high sweep).\r\n   */\r\n  playEncounterStart() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'sawtooth';\r\n      osc.frequency.setValueAtTime(130, now);\r\n      osc.frequency.exponentialRampToValueAtTime(520, now + 0.18);\r\n\r\n      gain.gain.setValueAtTime(0.15, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.22);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes attack / damage impact sound.\r\n   */\r\n  playAttack() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'square';\r\n      osc.frequency.setValueAtTime(320, now);\r\n      osc.frequency.exponentialRampToValueAtTime(80, now + 0.09);\r\n\r\n      gain.gain.setValueAtTime(0.2, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.09);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.09);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes correct answer chime.\r\n   */\r\n  playCorrect() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const notes = [587.33, 880.00]; // D5, A5\r\n      const now = this.ctx.currentTime;\r\n\r\n      notes.forEach((freq, idx) => {\r\n        const start = now + idx * 0.07;\r\n        const osc = this.ctx.createOscillator();\r\n        const gain = this.ctx.createGain();\r\n\r\n        osc.type = 'triangle';\r\n        osc.frequency.setValueAtTime(freq, start);\r\n\r\n        gain.gain.setValueAtTime(0.2, start);\r\n        gain.gain.exponentialRampToValueAtTime(0.001, start + 0.18);\r\n\r\n        osc.connect(gain);\r\n        gain.connect(this.ctx.destination);\r\n\r\n        osc.start(start);\r\n        osc.stop(start + 0.18);\r\n      });\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes incorrect answer tone (descending minor interval).\r\n   */\r\n  playWrong() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const now = this.ctx.currentTime;\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n\r\n      osc.type = 'sawtooth';\r\n      osc.frequency.setValueAtTime(260, now);\r\n      osc.frequency.exponentialRampToValueAtTime(140, now + 0.2);\r\n\r\n      gain.gain.setValueAtTime(0.14, now);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.2);\r\n\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n\r\n      osc.start(now);\r\n      osc.stop(now + 0.2);\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Synthesizes victory fanfare on quest / boss completion.\r\n   */\r\n  playFanfare() {\r\n    if (this.muted) return;\r\n    this.init();\r\n    if (!this.ctx) return;\r\n\r\n    try {\r\n      const notes = [523.25, 659.25, 783.99, 1046.50]; // C5, E5, G5, C6\r\n      const now = this.ctx.currentTime;\r\n\r\n      notes.forEach((freq, idx) => {\r\n        const start = now + idx * 0.09;\r\n        const duration = idx === 3 ? 0.35 : 0.12;\r\n        const osc = this.ctx.createOscillator();\r\n        const gain = this.ctx.createGain();\r\n\r\n        osc.type = 'triangle';\r\n        osc.frequency.setValueAtTime(freq, start);\r\n\r\n        gain.gain.setValueAtTime(0.22, start);\r\n        gain.gain.exponentialRampToValueAtTime(0.001, start + duration);\r\n\r\n        osc.connect(gain);\r\n        gain.connect(this.ctx.destination);\r\n\r\n        osc.start(start);\r\n        osc.stop(start + duration);\r\n      });\r\n    } catch {\r\n      // Audio play failed safely\r\n    }\r\n  }\r\n}\r\n\r\nconst soundEngine = new SoundEngine();\n\n/* --- DUAL KEYBOARD & TOUCH INPUT --- */\n\n// src/client/input.js — Dual Keyboard & Touch Input Abstraction\r\n// Handles mobile touch virtual D-Pad and keyboard navigation seamlessly.\r\n\r\nclass InputManager {\r\n  constructor() {\r\n    this.keysDown = new Set();\r\n    this.touchDown = new Set();\r\n    this.justPressed = new Set();\r\n    this.previousFrame = new Set();\r\n\r\n    // Map keyboard codes to logical game actions\r\n    this.keyMap = {\r\n      ArrowUp: 'up',\r\n      KeyW: 'up',\r\n      KeyK: 'up',\r\n      ArrowDown: 'down',\r\n      KeyS: 'down',\r\n      KeyJ: 'down',\r\n      ArrowLeft: 'left',\r\n      KeyA: 'left',\r\n      KeyH: 'left',\r\n      ArrowRight: 'right',\r\n      KeyD: 'right',\r\n      KeyL: 'right',\r\n      Space: 'action',\r\n      Enter: 'action',\r\n      KeyZ: 'action',\r\n      Escape: 'menu',\r\n      KeyM: 'menu',\r\n      KeyX: 'menu',\r\n    };\r\n\r\n    this.onKeyDown = this.onKeyDown.bind(this);\r\n    this.onKeyUp = this.onKeyUp.bind(this);\r\n  }\r\n\r\n  /**\r\n   * Initializes browser keyboard listeners if running in a DOM environment.\r\n   */\r\n  initKeyboard(target = globalThis.window) {\r\n    if (!target || typeof target.addEventListener !== 'function') return;\r\n    target.addEventListener('keydown', this.onKeyDown);\r\n    target.addEventListener('keyup', this.onKeyUp);\r\n  }\r\n\r\n  /**\r\n   * Cleans up browser listeners.\r\n   */\r\n  destroy(target = globalThis.window) {\r\n    if (!target || typeof target.removeEventListener !== 'function') return;\r\n    target.removeEventListener('keydown', this.onKeyDown);\r\n    target.removeEventListener('keyup', this.onKeyUp);\r\n  }\r\n\r\n  onKeyDown(event) {\r\n    const action = this.keyMap[event.code];\r\n    if (action) {\r\n      // Prevent browser scroll on arrow keys / spacebar during gameplay\r\n      if (['up', 'down', 'left', 'right', 'action'].includes(action)) {\r\n        if (typeof document !== 'undefined' && (event.target === document.body || (event.target && event.target.tagName === 'CANVAS'))) {\r\n          if (typeof event.preventDefault === 'function') {\r\n            event.preventDefault();\r\n          }\r\n        }\r\n      }\r\n      if (!this.keysDown.has(action)) {\r\n        this.justPressed.add(action);\r\n      }\r\n      this.keysDown.add(action);\r\n    }\r\n  }\r\n\r\n  onKeyUp(event) {\r\n    const action = this.keyMap[event.code];\r\n    if (action) {\r\n      this.keysDown.delete(action);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Sets touch action state programmatically (e.g. from virtual D-Pad or on-screen buttons).\r\n   * @param {string} action - 'up' | 'down' | 'left' | 'right' | 'action' | 'menu'\r\n   * @param {boolean} isPressed\r\n   */\r\n  setTouchAction(action, isPressed) {\r\n    if (isPressed) {\r\n      if (!this.touchDown.has(action)) {\r\n        this.justPressed.add(action);\r\n      }\r\n      this.touchDown.add(action);\r\n    } else {\r\n      this.touchDown.delete(action);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Checks if an action is currently held down via keyboard or touch.\r\n   * @param {string} action\r\n   * @returns {boolean}\r\n   */\r\n  isDown(action) {\r\n    return this.keysDown.has(action) || this.touchDown.has(action);\r\n  }\r\n\r\n  /**\r\n   * Checks if an action was newly triggered this frame.\r\n   * @param {string} action\r\n   * @returns {boolean}\r\n   */\r\n  isJustPressed(action) {\r\n    return this.justPressed.has(action);\r\n  }\r\n\r\n  /**\r\n   * Advance frame buffer — clears single-frame trigger events.\r\n   * Call once per animation frame tick.\r\n   */\r\n  update() {\r\n    this.justPressed.clear();\r\n  }\r\n\r\n  /**\r\n   * Binds virtual D-Pad touch/pointer events to HTML elements.\r\n   * Ensures touch-action: none and minimum 48px touch target support.\r\n   */\r\n  bindVirtualControls(elements) {\r\n    if (!elements) return;\r\n\r\n    const setupButton = (el, action) => {\r\n      if (!el) return;\r\n\r\n      const handlePress = (e) => {\r\n        if (e.cancelable) e.preventDefault();\r\n        this.setTouchAction(action, true);\r\n        el.setAttribute('data-active', 'true');\r\n      };\r\n\r\n      const handleRelease = (e) => {\r\n        if (e.cancelable) e.preventDefault();\r\n        this.setTouchAction(action, false);\r\n        el.removeAttribute('data-active');\r\n      };\r\n\r\n      el.addEventListener('pointerdown', handlePress);\r\n      el.addEventListener('pointerup', handleRelease);\r\n      el.addEventListener('pointercancel', handleRelease);\r\n      el.addEventListener('pointerleave', handleRelease);\r\n    };\r\n\r\n    if (elements.up) setupButton(elements.up, 'up');\r\n    if (elements.down) setupButton(elements.down, 'down');\r\n    if (elements.left) setupButton(elements.left, 'left');\r\n    if (elements.right) setupButton(elements.right, 'right');\r\n    if (elements.action) setupButton(elements.action, 'action');\r\n    if (elements.menu) setupButton(elements.menu, 'menu');\r\n  }\r\n}\n\n/* --- ENCOUNTER COMBAT ENGINE --- */\n\n// src/client/encounter.js — Turn-Based Question Combat State Machine\r\n// Authoritative single-player encounter controller for dungeons and boss battles.\r\n\r\n\r\nclass EncounterEngine {\r\n  constructor(encounters = [], questionBank = []) {\r\n    this.encounters = encounters;\r\n    this.questionBank = questionBank;\r\n    this.questionMap = new Map(questionBank.map(q => [q.id, q]));\r\n\r\n    // State machine states: 'IDLE' | 'QUESTION_ACTIVE' | 'ANSWER_FEEDBACK' | 'ENCOUNTER_VICTORY' | 'PLAYER_DEFEATED'\r\n    this.state = 'IDLE';\r\n\r\n    this.currentEncounterIndex = 0;\r\n    this.activeEncounter = null;\r\n    this.activeQuestion = null;\r\n    this.activeQuestionSecret = null; // Contains answerKey (kept internal)\r\n\r\n    // Combat attributes\r\n    this.maxPlayerHp = 3;\r\n    this.playerHp = 3;\r\n    this.enemyHp = 1;\r\n    this.bossQuestionIndex = 0;\r\n\r\n    // Tracking\r\n    this.completed = false;\r\n    this.lastResult = null;\r\n  }\r\n\r\n  /**\r\n   * Starts a specific encounter by index or the current encounter.\r\n   * @param {number} [index]\r\n   * @returns {object} Active encounter definition\r\n   */\r\n  startEncounter(index = this.currentEncounterIndex) {\r\n    if (index >= this.encounters.length) {\r\n      this.state = 'IDLE';\r\n      this.completed = true;\r\n      return null;\r\n    }\r\n\r\n    this.currentEncounterIndex = index;\r\n    this.activeEncounter = this.encounters[index];\r\n    this.enemyHp = this.activeEncounter.hp;\r\n    this.bossQuestionIndex = 0;\r\n\r\n    this.prepareNextQuestion();\r\n    this.state = 'QUESTION_ACTIVE';\r\n    return this.activeEncounter;\r\n  }\r\n\r\n  /**\r\n   * Loads the current question for this encounter step without exposing answerKey.\r\n   */\r\n  prepareNextQuestion() {\r\n    let questionId = this.activeEncounter.questionId;\r\n    if (this.activeEncounter.questionIds && Array.isArray(this.activeEncounter.questionIds)) {\r\n      questionId = this.activeEncounter.questionIds[this.bossQuestionIndex] || this.activeEncounter.questionIds[0];\r\n    }\r\n\r\n    const fullQuestion = this.questionMap.get(questionId);\r\n    if (!fullQuestion) {\r\n      throw new Error(`Question ${questionId} not found in question bank`);\r\n    }\r\n\r\n    this.activeQuestionSecret = fullQuestion;\r\n    this.activeQuestion = sanitizeQuestionForClient(fullQuestion);\r\n  }\r\n\r\n  /**\r\n   * Submits a player's choice ('a', 'b', 'c', or 'd').\r\n   * Evaluates correctness, updates HP, and returns result payload.\r\n   * @param {string} choiceId\r\n   */\r\n  submitAnswer(choiceId) {\r\n    if (this.state !== 'QUESTION_ACTIVE') {\r\n      throw new Error(`Cannot submit answer while in state: ${this.state}`);\r\n    }\r\n\r\n    const isCorrect = choiceId === this.activeQuestionSecret.answerKey;\r\n    const explanation = this.activeQuestionSecret.explanation;\r\n\r\n    let enemyDefeated = false;\r\n    let playerDefeated = false;\r\n\r\n    if (isCorrect) {\r\n      this.enemyHp = Math.max(0, this.enemyHp - 1);\r\n      if (this.enemyHp === 0) {\r\n        enemyDefeated = true;\r\n        this.state = 'ENCOUNTER_VICTORY';\r\n        if (this.activeEncounter.type === 'boss') {\r\n          this.completed = true;\r\n        }\r\n      } else {\r\n        this.bossQuestionIndex++;\r\n        this.state = 'ANSWER_FEEDBACK';\r\n      }\r\n    } else {\r\n      this.playerHp = Math.max(0, this.playerHp - 1);\r\n      if (this.playerHp === 0) {\r\n        playerDefeated = true;\r\n        this.state = 'PLAYER_DEFEATED';\r\n      } else {\r\n        this.state = 'ANSWER_FEEDBACK';\r\n      }\r\n    }\r\n\r\n    this.lastResult = {\r\n      correct: isCorrect,\r\n      explanation,\r\n      enemyDefeated,\r\n      playerDefeated,\r\n      playerHp: this.playerHp,\r\n      enemyHp: this.enemyHp,\r\n    };\r\n\r\n    return this.lastResult;\r\n  }\r\n\r\n  /**\r\n   * Advances from feedback to next question or cleans up.\r\n   */\r\n  advance() {\r\n    if (this.state === 'ANSWER_FEEDBACK') {\r\n      this.prepareNextQuestion();\r\n      this.state = 'QUESTION_ACTIVE';\r\n      return true;\r\n    }\r\n    return false;\r\n  }\r\n\r\n  /**\r\n   * Retries the current encounter upon defeat, preventing soft locks.\r\n   */\r\n  retry() {\r\n    this.playerHp = this.maxPlayerHp;\r\n    this.enemyHp = this.activeEncounter.maxHp;\r\n    this.bossQuestionIndex = 0;\r\n    this.prepareNextQuestion();\r\n    this.state = 'QUESTION_ACTIVE';\r\n  }\r\n\r\n  /**\r\n   * Advances to next dungeon encounter.\r\n   */\r\n  nextEncounter() {\r\n    if (this.currentEncounterIndex + 1 < this.encounters.length) {\r\n      return this.startEncounter(this.currentEncounterIndex + 1);\r\n    }\r\n    this.state = 'IDLE';\r\n    this.completed = true;\r\n    return null;\r\n  }\r\n\r\n  /**\r\n   * Resets entire dungeon to initial state.\r\n   */\r\n  resetDungeon() {\r\n    this.currentEncounterIndex = 0;\r\n    this.activeEncounter = null;\r\n    this.activeQuestion = null;\r\n    this.activeQuestionSecret = null;\r\n    this.playerHp = this.maxPlayerHp;\r\n    this.enemyHp = 1;\r\n    this.bossQuestionIndex = 0;\r\n    this.state = 'IDLE';\r\n    this.completed = false;\r\n    this.lastResult = null;\r\n  }\r\n}\n\n/* --- CANVAS 2D RENDERER --- */\n\n// src/client/renderer.js — 2D Canvas Procedural Game Engine\r\n// Renders 320x240 retro world with crisp pixel scaling, multi-zone map, and procedural sprites.\r\n\r\n\r\nclass GameRenderer {\r\n  constructor(canvasElement) {\r\n    this.canvas = canvasElement;\r\n    this.ctx = canvasElement ? canvasElement.getContext('2d') : null;\r\n    this.atlas = null;\r\n\r\n    // Viewport dimensions\r\n    this.width = VIEWPORT.LOGICAL_WIDTH;\r\n    this.height = VIEWPORT.LOGICAL_HEIGHT;\r\n    this.tileSize = VIEWPORT.TILE_SIZE;\r\n\r\n    // World map grid: 20 cols x 16 rows (320px x 256px world)\r\n    this.cols = 20;\r\n    this.rows = 16;\r\n    this.worldWidth = this.cols * this.tileSize;\r\n    this.worldHeight = this.rows * this.tileSize;\r\n\r\n    // Camera\r\n    this.camera = { x: 0, y: 0 };\r\n\r\n    // Player state\r\n    this.player = {\r\n      x: 152, // Center of world\r\n      y: 120,\r\n      direction: 'down',\r\n      speed: 80, // pixels per second\r\n      width: 16,\r\n      height: 16,\r\n      moving: false,\r\n    };\r\n\r\n    // Active zone: 'hub' | 'route' | 'dungeon'\r\n    this.currentZone = 'hub';\r\n\r\n    // Shrines for the 5 KAAC Academic Subjects (in Hub)\r\n    this.shrines = [\r\n      { id: 'math', col: 3, row: 3, subject: SUBJECTS.MATH, label: 'Cipher Portal' },\r\n      { id: 'science', col: 16, row: 3, subject: SUBJECTS.SCIENCE, label: 'Verdant Portal' },\r\n      { id: 'social_studies', col: 3, row: 12, subject: SUBJECTS.SOCIAL_STUDIES, label: 'Time Portal' },\r\n      { id: 'language_arts', col: 16, row: 12, subject: SUBJECTS.LANGUAGE_ARTS, label: 'Archive Portal' },\r\n      { id: 'arts_humanities', col: 9, row: 2, subject: SUBJECTS.ARTS_HUMANITIES, label: 'Gallery Portal' },\r\n    ];\r\n\r\n    // NPC: Berea Sage in Hub\r\n    this.npc = {\r\n      id: 'npc_sage',\r\n      name: 'Elder Sage of Berea',\r\n      col: 10,\r\n      row: 5,\r\n      dialogue: 'Welcome, young Scholar! The Commonwealth realms are tested by ignorance. Take the northern trail to the Verdant Sanctuary to prove your knowledge!',\r\n    };\r\n\r\n    // Dungeon Encounters placed across the 5 chambers of the Verdant Sanctuary\r\n    this.dungeonEntities = [\r\n      { index: 0, id: 'enc_sproutling', col: 9, row: 12, sprite: 'sproutling', label: 'Bramble Sproutling', defeated: false },\r\n      { index: 1, id: 'enc_cave_wisp', col: 5, row: 9, sprite: 'wisp', label: 'Cipher Wisp', defeated: false },\r\n      { index: 2, id: 'enc_chrono_sentry', col: 14, row: 9, sprite: 'sentry', label: 'Pioneer Sentry', defeated: false },\r\n      { index: 3, id: 'enc_word_specter', col: 9, row: 6, sprite: 'specter', label: 'Archival Specter', defeated: false },\r\n      { index: 4, id: 'enc_boss_guardian', col: 9, row: 2, sprite: 'boss', label: 'Overgrown Guardian (Boss)', defeated: false },\r\n    ];\r\n\r\n    // Map generators\r\n    this.maps = {\r\n      hub: this.generateHubMap(),\r\n      route: this.generateRouteMap(),\r\n      dungeon: this.generateDungeonMap(),\r\n    };\r\n\r\n    this.map = this.maps.hub;\r\n\r\n    // Nearby interaction prompt\r\n    this.activeInteraction = null;\r\n\r\n    if (typeof document !== 'undefined') {\r\n      this.atlas = createTileAtlas();\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Generates Starter Village / Crossroads Hub (20x16).\r\n   * 0=grass, 1=path, 2=water, 3=wall, 4=trees\r\n   */\r\n  generateHubMap() {\r\n    const tiles = [];\r\n    for (let r = 0; r < this.rows; r++) {\r\n      const row = [];\r\n      for (let c = 0; c < this.cols; c++) {\r\n        // Boundary trees, except northern exit opening at c=9, 10\r\n        if (r === 0 && (c === 9 || c === 10)) {\r\n          row.push(1); // North exit opening to route\r\n        } else if (r === 0 || r === this.rows - 1 || c === 0 || c === this.cols - 1) {\r\n          row.push(4);\r\n        } else if (r === 8 || c === 9 || c === 10) {\r\n          row.push(1); // Central crossroads path\r\n        } else if (r >= 11 && r <= 13 && c >= 9 && c <= 11) {\r\n          row.push(2); // Decorative pond\r\n        } else {\r\n          row.push(0); // Grassy meadows\r\n        }\r\n      }\r\n      tiles.push(row);\r\n    }\r\n    return tiles;\r\n  }\r\n\r\n  /**\r\n   * Generates Route 1: Red River Trail (20x16).\r\n   * Winding path north toward the dungeon entrance.\r\n   */\r\n  generateRouteMap() {\r\n    const tiles = [];\r\n    for (let r = 0; r < this.rows; r++) {\r\n      const row = [];\r\n      for (let c = 0; c < this.cols; c++) {\r\n        // Boundaries with north opening to dungeon and south opening to hub\r\n        if ((r === 0 || r === this.rows - 1) && (c === 9 || c === 10)) {\r\n          row.push(1);\r\n        } else if (r === 0 || r === this.rows - 1 || c === 0 || c === this.cols - 1) {\r\n          row.push(4);\r\n        }\r\n        // Winding river cutting across east side\r\n        else if (c === 15 && r > 2 && r < 14) {\r\n          row.push(2);\r\n        }\r\n        // Winding trail connecting south to north\r\n        else if ((r >= 11 && (c === 9 || c === 10)) ||\r\n                 (r >= 8 && r <= 10 && (c >= 6 && c <= 10)) ||\r\n                 (r >= 5 && r <= 7 && (c >= 6 && c <= 13)) ||\r\n                 (r <= 4 && (c === 9 || c === 10))) {\r\n          row.push(1);\r\n        } else {\r\n          row.push(0);\r\n        }\r\n      }\r\n      tiles.push(row);\r\n    }\r\n    return tiles;\r\n  }\r\n\r\n  /**\r\n   * Generates The Verdant Sanctuary Dungeon (20x16).\r\n   * 3=stone wall, 5=stone floor, 6=gateway, 1=path\r\n   */\r\n  generateDungeonMap() {\r\n    const tiles = [];\r\n    for (let r = 0; r < this.rows; r++) {\r\n      const row = [];\r\n      for (let c = 0; c < this.cols; c++) {\r\n        // Outer stone walls, with southern exit opening\r\n        if (r === this.rows - 1 && (c === 9 || c === 10)) {\r\n          row.push(5);\r\n        } else if (r === 0 || r === this.rows - 1 || c === 0 || c === this.cols - 1) {\r\n          row.push(3);\r\n        }\r\n        // Boss chamber north boundary with gate opening\r\n        else if (r === 4 && (c < 8 || c > 11)) {\r\n          row.push(3);\r\n        } else if (r === 4 && (c === 9 || c === 10)) {\r\n          row.push(6); // Boss gateway\r\n        }\r\n        // Side chamber dividers\r\n        else if ((c === 4 || c === 15) && (r >= 7 && r <= 11)) {\r\n          row.push(3);\r\n        } else {\r\n          row.push(5); // Dungeon stone floor\r\n        }\r\n      }\r\n      tiles.push(row);\r\n    }\r\n    return tiles;\r\n  }\r\n\r\n  /**\r\n   * Changes the active zone and positions the player.\r\n   * @param {'hub'|'route'|'dungeon'} zone\r\n   * @param {number} startX\r\n   * @param {number} startY\r\n   */\r\n  changeZone(zone, startX, startY) {\r\n    if (!this.maps[zone]) return;\r\n    this.currentZone = zone;\r\n    this.map = this.maps[zone];\r\n    this.player.x = startX;\r\n    this.player.y = startY;\r\n    this.camera.x = startX - this.width / 2;\r\n    this.camera.y = startY - this.height / 2;\r\n    this.activeInteraction = null;\r\n  }\r\n\r\n  /**\r\n   * Checks if a tile is solid (impassable).\r\n   * 2=water, 3=stone wall, 4=trees\r\n   */\r\n  isTileSolid(col, row) {\r\n    if (col < 0 || col >= this.cols || row < 0 || row >= this.rows) return true;\r\n    const tile = this.map[row][col];\r\n    return tile === 2 || tile === 3 || tile === 4;\r\n  }\r\n\r\n  /**\r\n   * Resizes canvas to match container while preserving crisp pixel ratio.\r\n   */\r\n  handleResize(containerWidth, containerHeight) {\r\n    if (!this.canvas) return;\r\n\r\n    const scaleX = containerWidth / this.width;\r\n    const scaleY = containerHeight / this.height;\r\n    const scale = Math.max(1, Math.min(scaleX, scaleY));\r\n\r\n    const displayWidth = Math.floor(this.width * scale);\r\n    const displayHeight = Math.floor(this.height * scale);\r\n\r\n    this.canvas.style.width = `${displayWidth}px`;\r\n    this.canvas.style.height = `${displayHeight}px`;\r\n\r\n    this.canvas.width = this.width;\r\n    this.canvas.height = this.height;\r\n\r\n    if (this.ctx) {\r\n      this.ctx.imageSmoothingEnabled = false;\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Updates game logic: input polling, player movement, collisions, transitions, and camera.\r\n   * @param {number} dt Delta time in seconds\r\n   * @param {import('./input.js').InputManager} input\r\n   * @param {boolean} reducedMotion\r\n   */\r\n  update(dt, input, reducedMotion = false) {\r\n    if (!input) return;\r\n\r\n    let dx = 0;\r\n    let dy = 0;\r\n\r\n    if (input.isDown('up')) {\r\n      dy -= 1;\r\n      this.player.direction = 'up';\r\n    }\r\n    if (input.isDown('down')) {\r\n      dy += 1;\r\n      this.player.direction = 'down';\r\n    }\r\n    if (input.isDown('left')) {\r\n      dx -= 1;\r\n      this.player.direction = 'left';\r\n    }\r\n    if (input.isDown('right')) {\r\n      dx += 1;\r\n      this.player.direction = 'right';\r\n    }\r\n\r\n    this.player.moving = dx !== 0 || dy !== 0;\r\n\r\n    if (this.player.moving) {\r\n      const length = Math.hypot(dx, dy);\r\n      const moveX = (dx / length) * this.player.speed * dt;\r\n      const moveY = (dy / length) * this.player.speed * dt;\r\n\r\n      const newX = this.player.x + moveX;\r\n      const newY = this.player.y + moveY;\r\n\r\n      // Check tile collision for bounding box\r\n      const pW = this.player.width;\r\n      const pH = this.player.height;\r\n\r\n      // X-axis collision check\r\n      const colLeft = Math.floor(newX / this.tileSize);\r\n      const colRight = Math.floor((newX + pW - 1) / this.tileSize);\r\n      const rowTopCurrent = Math.floor(this.player.y / this.tileSize);\r\n      const rowBottomCurrent = Math.floor((this.player.y + pH - 1) / this.tileSize);\r\n\r\n      const collisionX =\r\n        this.isTileSolid(colLeft, rowTopCurrent) ||\r\n        this.isTileSolid(colRight, rowTopCurrent) ||\r\n        this.isTileSolid(colLeft, rowBottomCurrent) ||\r\n        this.isTileSolid(colRight, rowBottomCurrent);\r\n\r\n      if (!collisionX) {\r\n        this.player.x = newX;\r\n      }\r\n\r\n      // Y-axis collision check\r\n      const colLeftCurrent = Math.floor(this.player.x / this.tileSize);\r\n      const colRightCurrent = Math.floor((this.player.x + pW - 1) / this.tileSize);\r\n      const rowTop = Math.floor(newY / this.tileSize);\r\n      const rowBottom = Math.floor((newY + pH - 1) / this.tileSize);\r\n\r\n      const collisionY =\r\n        this.isTileSolid(colLeftCurrent, rowTop) ||\r\n        this.isTileSolid(colRightCurrent, rowTop) ||\r\n        this.isTileSolid(colLeftCurrent, rowBottom) ||\r\n        this.isTileSolid(colRightCurrent, rowBottom);\r\n\r\n      if (!collisionY) {\r\n        this.player.y = newY;\r\n      }\r\n\r\n      // World boundary clamping\r\n      const minX = this.tileSize;\r\n      const maxX = this.worldWidth - this.tileSize - this.player.width;\r\n      const minY = 0; // Allow edge triggers\r\n      const maxY = this.worldHeight - this.player.height;\r\n\r\n      this.player.x = Math.max(minX, Math.min(maxX, this.player.x));\r\n      this.player.y = Math.max(minY, Math.min(maxY, this.player.y));\r\n\r\n      // Zone Transition Triggers\r\n      this.checkZoneTransitions();\r\n    }\r\n\r\n    // Camera centering with clamping\r\n    const targetCamX = this.player.x + this.player.width / 2 - this.width / 2;\r\n    const targetCamY = this.player.y + this.player.height / 2 - this.height / 2;\r\n    const maxCamX = Math.max(0, this.worldWidth - this.width);\r\n    const maxCamY = Math.max(0, this.worldHeight - this.height);\r\n\r\n    if (reducedMotion) {\r\n      this.camera.x = Math.max(0, Math.min(maxCamX, targetCamX));\r\n      this.camera.y = Math.max(0, Math.min(maxCamY, targetCamY));\r\n    } else {\r\n      this.camera.x += (Math.max(0, Math.min(maxCamX, targetCamX)) - this.camera.x) * 0.1;\r\n      this.camera.y += (Math.max(0, Math.min(maxCamY, targetCamY)) - this.camera.y) * 0.1;\r\n    }\r\n\r\n    // Check interaction proximity\r\n    this.checkInteractions();\r\n  }\r\n\r\n  /**\r\n   * Checks if player stepped on a zone boundary transition.\r\n   */\r\n  checkZoneTransitions() {\r\n    const pCol = Math.floor((this.player.x + this.player.width / 2) / this.tileSize);\r\n    const pRow = Math.floor((this.player.y + this.player.height / 2) / this.tileSize);\r\n\r\n    // Hub -> Route (North edge at col 9-10)\r\n    if (this.currentZone === 'hub' && pRow <= 0 && (pCol === 9 || pCol === 10)) {\r\n      this.changeZone('route', 152, 220);\r\n      return;\r\n    }\r\n\r\n    // Route -> Hub (South edge at col 9-10)\r\n    if (this.currentZone === 'route' && pRow >= 15 && (pCol === 9 || pCol === 10)) {\r\n      this.changeZone('hub', 152, 20);\r\n      return;\r\n    }\r\n\r\n    // Route -> Dungeon (North edge at col 9-10)\r\n    if (this.currentZone === 'route' && pRow <= 0 && (pCol === 9 || pCol === 10)) {\r\n      this.changeZone('dungeon', 152, 220);\r\n      return;\r\n    }\r\n\r\n    // Dungeon -> Route (South edge at col 9-10)\r\n    if (this.currentZone === 'dungeon' && pRow >= 15 && (pCol === 9 || pCol === 10)) {\r\n      this.changeZone('route', 152, 20);\r\n      return;\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Checks proximity to NPCs, Shrines, and Dungeon Encounters.\r\n   */\r\n  checkInteractions() {\r\n    this.activeInteraction = null;\r\n    const pCenterX = this.player.x + this.player.width / 2;\r\n    const pCenterY = this.player.y + this.player.height / 2;\r\n\r\n    // 1. Hub Shrines\r\n    if (this.currentZone === 'hub') {\r\n      for (const shrine of this.shrines) {\r\n        const sX = shrine.col * this.tileSize + this.tileSize / 2;\r\n        const sY = shrine.row * this.tileSize + this.tileSize / 2;\r\n        if (Math.hypot(pCenterX - sX, pCenterY - sY) < 26) {\r\n          this.activeInteraction = { ...shrine, type: 'shrine' };\r\n          return;\r\n        }\r\n      }\r\n\r\n      // Hub Sage NPC\r\n      const npcX = this.npc.col * this.tileSize + this.tileSize / 2;\r\n      const npcY = this.npc.row * this.tileSize + this.tileSize / 2;\r\n      if (Math.hypot(pCenterX - npcX, pCenterY - npcY) < 26) {\r\n        this.activeInteraction = { ...this.npc, type: 'npc', label: this.npc.name };\r\n        return;\r\n      }\r\n    }\r\n\r\n    // 2. Dungeon Encounters\r\n    if (this.currentZone === 'dungeon') {\r\n      for (const enc of this.dungeonEntities) {\r\n        if (!enc.defeated) {\r\n          const eX = enc.col * this.tileSize + this.tileSize / 2;\r\n          const eY = enc.row * this.tileSize + this.tileSize / 2;\r\n          if (Math.hypot(pCenterX - eX, pCenterY - eY) < 26) {\r\n            this.activeInteraction = { ...enc, type: 'encounter' };\r\n            return;\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Main rendering routine.\r\n   * @param {number} time Current timestamp\r\n   */\r\n  render(time = 0) {\r\n    if (!this.ctx) return;\r\n    const ctx = this.ctx;\r\n\r\n    ctx.fillStyle = PALETTE.BG_DARK;\r\n    ctx.fillRect(0, 0, this.width, this.height);\r\n\r\n    ctx.save();\r\n    ctx.translate(-Math.floor(this.camera.x), -Math.floor(this.camera.y));\r\n\r\n    // 1. Draw Tilemap\r\n    for (let r = 0; r < this.rows; r++) {\r\n      for (let c = 0; c < this.cols; c++) {\r\n        const tileType = this.map[r][c];\r\n        const destX = c * this.tileSize;\r\n        const destY = r * this.tileSize;\r\n\r\n        if (this.atlas) {\r\n          const srcX = tileType * this.tileSize;\r\n          ctx.drawImage(this.atlas, srcX, 0, 16, 16, destX, destY, 16, 16);\r\n        } else {\r\n          // Fallback solid tiles\r\n          const fallbackColors = [\r\n            PALETTE.SCIENCE, PALETTE.SURFACE_ELEVATED, PALETTE.MATH,\r\n            PALETTE.SURFACE, PALETTE.BG_DARK, PALETTE.SURFACE, PALETTE.BORDER_FOCUS,\r\n          ];\r\n          ctx.fillStyle = fallbackColors[tileType] || PALETTE.BG_DARK;\r\n          ctx.fillRect(destX, destY, 16, 16);\r\n        }\r\n      }\r\n    }\r\n\r\n    // 2. Zone-specific Entities\r\n    if (this.currentZone === 'hub') {\r\n      // 5 Shrines\r\n      for (const shrine of this.shrines) {\r\n        const sx = shrine.col * this.tileSize;\r\n        const sy = shrine.row * this.tileSize;\r\n\r\n        ctx.fillStyle = PALETTE.SURFACE_ELEVATED;\r\n        ctx.fillRect(sx, sy + 6, 16, 10);\r\n        ctx.fillStyle = PALETTE.SURFACE_ACCENT;\r\n        ctx.fillRect(sx + 2, sy + 4, 12, 2);\r\n\r\n        ctx.fillStyle = shrine.subject.color;\r\n        ctx.fillRect(sx + 4, sy - 2, 8, 8);\r\n\r\n        const pulse = Math.sin(time / 250 + shrine.col) * 1.5;\r\n        ctx.fillStyle = PALETTE.TEXT_PRIMARY;\r\n        ctx.fillRect(sx + 6, sy + Math.floor(pulse), 4, 4);\r\n      }\r\n\r\n      // Berea Sage NPC\r\n      const nx = this.npc.col * this.tileSize;\r\n      const ny = this.npc.row * this.tileSize;\r\n      renderPixelSprite(ctx, NPC_SPRITES.sage, nx, ny, 2);\r\n    }\r\n\r\n    if (this.currentZone === 'dungeon') {\r\n      // Draw 5 dungeon encounters\r\n      for (const enc of this.dungeonEntities) {\r\n        const ex = enc.col * this.tileSize;\r\n        const ey = enc.row * this.tileSize;\r\n\r\n        if (!enc.defeated) {\r\n          const sprite = ENEMY_SPRITES[enc.sprite];\r\n          if (sprite) {\r\n            renderPixelSprite(ctx, sprite, ex, ey, 2);\r\n          }\r\n          // Glowing aura under enemy\r\n          const glow = Math.sin(time / 200 + enc.index) * 2;\r\n          ctx.fillStyle = enc.sprite === 'boss' ? PALETTE.GOLD : PALETTE.BORDER_FOCUS;\r\n          ctx.fillRect(ex + 4, ey + 14, 8, 2);\r\n        } else {\r\n          // Cleared marker / defeated wildflower\r\n          ctx.fillStyle = PALETTE.SUCCESS;\r\n          ctx.fillRect(ex + 6, ey + 10, 4, 4);\r\n        }\r\n      }\r\n    }\r\n\r\n    // 3. Draw Player Character\r\n    const sprite = HERO_SPRITES[this.player.direction] || HERO_SPRITES.down;\r\n    renderPixelSprite(ctx, sprite, this.player.x, this.player.y, 2);\r\n\r\n    // 4. Draw Interaction Prompt\r\n    if (this.activeInteraction) {\r\n      const promptX = Math.floor(this.player.x - 28);\r\n      const promptY = Math.floor(this.player.y - 14);\r\n\r\n      ctx.fillStyle = PALETTE.SURFACE;\r\n      ctx.fillRect(promptX, promptY, 72, 12);\r\n      ctx.strokeStyle = PALETTE.BORDER_FOCUS;\r\n      ctx.lineWidth = 1;\r\n      ctx.strokeRect(promptX, promptY, 72, 12);\r\n\r\n      ctx.fillStyle = PALETTE.TEXT_PRIMARY;\r\n      ctx.font = '8px system-ui, sans-serif';\r\n      ctx.textAlign = 'center';\r\n      const shortLabel = this.activeInteraction.label.split(' ')[0];\r\n      ctx.fillText(`[ACT] ${shortLabel}`, promptX + 36, promptY + 9);\r\n    }\r\n\r\n    ctx.restore();\r\n  }\r\n}\n\n/* --- SEMANTIC UI OVERLAY --- */\n\n// src/client/ui.js — Semantic Accessible UI Overlay\r\n// Follows WHATWG HTML Living Standard: explicit closing tags, type=\"button\", WCAG AA contrast.\r\n\r\n\r\nclass UIManager {\r\n  constructor(rootElement, playerProfile, callbacks = {}) {\r\n    this.root = rootElement;\r\n    this.player = playerProfile;\r\n    this.callbacks = callbacks;\r\n    this.activeTab = null;\r\n\r\n    this.render();\r\n    this.bindEvents();\r\n  }\r\n\r\n  render() {\r\n    if (!this.root) return;\r\n\r\n    this.root.innerHTML = `\r\n      <header class=\"game-hud\" role=\"banner\">\r\n        <div class=\"hud-player\">\r\n          <div class=\"avatar-badge\" aria-hidden=\"true\">\r\n            <span class=\"avatar-icon\">${getSvgIcon('sigil', PALETTE.BORDER_FOCUS, 22)}</span>\r\n          </div>\r\n          <div class=\"hud-meta\">\r\n            <div class=\"player-handle\" id=\"hud-handle\">${this.escapeHtml(this.player.handle)}</div>\r\n            <div class=\"player-stats\">\r\n              <span class=\"level-badge\" id=\"hud-level\">LV ${this.player.level}</span>\r\n              <div class=\"hp-bar-container\" title=\"Health: ${this.player.hp}/${this.player.maxHp}\">\r\n                <div class=\"hp-bar-fill\" id=\"hud-hp-bar\" style=\"width: ${(this.player.hp / this.player.maxHp) * 100}%\"></div>\r\n              </div>\r\n              <span class=\"gold-counter\">\r\n                <span class=\"gold-icon\" aria-hidden=\"true\">${getSvgIcon('scroll', PALETTE.GOLD, 14)}</span>\r\n                <span id=\"hud-gold\">${this.player.gold} G</span>\r\n              </span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <nav class=\"hud-nav\" aria-label=\"Game Navigation\">\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"map\" title=\"Regional Map\">\r\n            ${getSvgIcon('map', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Map</span>\r\n          </button>\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"quests\" title=\"Quest Log\">\r\n            ${getSvgIcon('quests', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Quests</span>\r\n          </button>\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"inventory\" title=\"Inventory\">\r\n            ${getSvgIcon('inventory', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Items</span>\r\n          </button>\r\n          <button type=\"button\" class=\"hud-btn\" data-tab=\"settings\" title=\"Game Settings\">\r\n            ${getSvgIcon('settings', PALETTE.TEXT_PRIMARY, 18)}\r\n            <span class=\"btn-label\">Settings</span>\r\n          </button>\r\n        </nav>\r\n      </header>\r\n\r\n      <!-- Active Overlay Panels (Modals) -->\r\n      <div id=\"panel-container\" class=\"panel-container\" hidden>\r\n        <section id=\"panel-content\" class=\"panel-card\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"panel-title\">\r\n          <header class=\"panel-header\">\r\n            <h2 id=\"panel-title\" class=\"panel-title\">Menu</h2>\r\n            <button type=\"button\" class=\"panel-close-btn\" id=\"panel-close\" title=\"Close Panel\" aria-label=\"Close Panel\">\r\n              ${getSvgIcon('close', PALETTE.TEXT_PRIMARY, 18)}\r\n            </button>\r\n          </header>\r\n          <div id=\"panel-body\" class=\"panel-body\"></div>\r\n        </section>\r\n      </div>\r\n\r\n      <!-- Dialogue / Interaction Banner -->\r\n      <div id=\"interaction-banner\" class=\"interaction-banner\" role=\"status\" aria-live=\"polite\" hidden>\r\n        <div class=\"interaction-content\" id=\"interaction-text\"></div>\r\n      </div>\r\n\r\n      <!-- Mobile On-Screen Virtual Controller -->\r\n      <div class=\"touch-controls\" id=\"touch-controls\" aria-label=\"Virtual Touch Controller\">\r\n        <div class=\"virtual-dpad\" aria-label=\"Directional Pad\">\r\n          <button type=\"button\" class=\"dpad-btn dpad-up\" id=\"btn-up\" aria-label=\"Move Up\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-left\" id=\"btn-left\" aria-label=\"Move Left\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-center\" aria-hidden=\"true\" tabindex=\"-1\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-right\" id=\"btn-right\" aria-label=\"Move Right\"></button>\r\n          <button type=\"button\" class=\"dpad-btn dpad-down\" id=\"btn-down\" aria-label=\"Move Down\"></button>\r\n        </div>\r\n\r\n        <div class=\"virtual-actions\" aria-label=\"Action Buttons\">\r\n          <button type=\"button\" class=\"action-btn btn-act\" id=\"btn-act\" aria-label=\"Action\">ACT</button>\r\n          <button type=\"button\" class=\"action-btn btn-menu\" id=\"btn-menu\" aria-label=\"Menu\">MENU</button>\r\n        </div>\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  bindEvents() {\r\n    // HUD tab buttons\r\n    const navButtons = this.root.querySelectorAll('.hud-btn[data-tab]');\r\n    navButtons.forEach(btn => {\r\n      btn.addEventListener('click', () => {\r\n        soundEngine.playClick();\r\n        const tab = btn.getAttribute('data-tab');\r\n        this.openTab(tab);\r\n      });\r\n    });\r\n\r\n    // Close panel button\r\n    const closeBtn = this.root.querySelector('#panel-close');\r\n    if (closeBtn) {\r\n      closeBtn.addEventListener('click', () => {\r\n        soundEngine.playClick();\r\n        this.closePanel();\r\n      });\r\n    }\r\n\r\n    // Close on escape key\r\n    this.root.addEventListener('keydown', (e) => {\r\n      if (e.key === 'Escape' && this.activeTab && this.activeTab !== 'encounter') {\r\n        this.closePanel();\r\n      }\r\n    });\r\n\r\n    // Virtual MENU button toggles settings or closes\r\n    const virtualMenuBtn = this.root.querySelector('#btn-menu');\r\n    if (virtualMenuBtn) {\r\n      virtualMenuBtn.addEventListener('click', () => {\r\n        if (this.activeTab) {\r\n          this.closePanel();\r\n        } else {\r\n          this.openTab('settings');\r\n        }\r\n      });\r\n    }\r\n  }\r\n\r\n  getTouchElements() {\r\n    return {\r\n      up: this.root.querySelector('#btn-up'),\r\n      down: this.root.querySelector('#btn-down'),\r\n      left: this.root.querySelector('#btn-left'),\r\n      right: this.root.querySelector('#btn-right'),\r\n      action: this.root.querySelector('#btn-act'),\r\n      menu: this.root.querySelector('#btn-menu'),\r\n    };\r\n  }\r\n\r\n  openTab(tab) {\r\n    if (this.activeTab === tab) {\r\n      this.closePanel();\r\n      return;\r\n    }\r\n\r\n    this.activeTab = tab;\r\n    const container = this.root.querySelector('#panel-container');\r\n    const title = this.root.querySelector('#panel-title');\r\n    const body = this.root.querySelector('#panel-body');\r\n\r\n    if (!container || !title || !body) return;\r\n\r\n    soundEngine.playAlert();\r\n    container.removeAttribute('hidden');\r\n\r\n    switch (tab) {\r\n      case 'map':\r\n        title.textContent = \"Commonwealth Realms (Governor's Cup)\";\r\n        body.innerHTML = this.renderMapPanel();\r\n        break;\r\n      case 'quests':\r\n        title.textContent = 'Curriculum Quests';\r\n        body.innerHTML = this.renderQuestsPanel();\r\n        break;\r\n      case 'inventory':\r\n        title.textContent = 'Scholar Inventory & Relics';\r\n        body.innerHTML = this.renderInventoryPanel();\r\n        break;\r\n      case 'settings':\r\n        title.textContent = 'Game Settings & Accessibility';\r\n        body.innerHTML = this.renderSettingsPanel();\r\n        this.bindSettingsEvents(body);\r\n        break;\r\n      default:\r\n        this.closePanel();\r\n        return;\r\n    }\r\n  }\r\n\r\n  closePanel() {\r\n    this.activeTab = null;\r\n    const container = this.root.querySelector('#panel-container');\r\n    if (container) {\r\n      container.setAttribute('hidden', '');\r\n    }\r\n  }\r\n\r\n  updatePlayerStats(player) {\r\n    this.player = player;\r\n    const levelEl = this.root.querySelector('#hud-level');\r\n    const hpBar = this.root.querySelector('#hud-hp-bar');\r\n    const goldEl = this.root.querySelector('#hud-gold');\r\n\r\n    if (levelEl) levelEl.textContent = `LV ${player.level}`;\r\n    if (hpBar) hpBar.style.width = `${Math.max(0, (player.hp / player.maxHp) * 100)}%`;\r\n    if (goldEl) goldEl.textContent = `${player.gold} G`;\r\n  }\r\n\r\n  renderMapPanel() {\r\n    const realms = Object.values(SUBJECTS);\r\n    return `\r\n      <div class=\"map-grid\">\r\n        ${realms.map(r => `\r\n          <article class=\"realm-card\" style=\"border-left: 4px solid ${r.color}\">\r\n            <h3 class=\"realm-title\" style=\"color: ${r.color}\">${this.escapeHtml(r.realm)}</h3>\r\n            <p class=\"realm-subject\">Subject: <strong>${this.escapeHtml(r.name)}</strong></p>\r\n            <p class=\"realm-boss\">Dungeon Boss: <em>${this.escapeHtml(r.boss)}</em></p>\r\n          </article>\r\n        `).join('')}\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  renderQuestsPanel() {\r\n    return `\r\n      <div class=\"quests-list\">\r\n        ${this.player.quests.map(q => `\r\n          <article class=\"quest-card\" style=\"border-left: 4px solid ${q.color}\">\r\n            <header class=\"quest-card-header\">\r\n              <h3 class=\"quest-title\">${this.escapeHtml(q.title)}</h3>\r\n              <span class=\"quest-badge status-${q.status}\">${this.escapeHtml(q.status.toUpperCase())}</span>\r\n            </header>\r\n            <p class=\"quest-desc\">${this.escapeHtml(q.description)}</p>\r\n            <footer class=\"quest-footer\">\r\n              <span class=\"quest-progress\">${this.escapeHtml(q.progress)}</span>\r\n              <span class=\"quest-rewards\">+${q.rewardXp} XP · +${q.rewardGold} Gold</span>\r\n            </footer>\r\n          </article>\r\n        `).join('')}\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  renderInventoryPanel() {\r\n    return `\r\n      <div class=\"inventory-grid\">\r\n        ${this.player.inventory.map(item => `\r\n          <article class=\"item-card\">\r\n            <div class=\"item-icon-box\" style=\"border: 1px solid ${item.color}\">\r\n              ${getSvgIcon(item.icon, item.color, 24)}\r\n            </div>\r\n            <div class=\"item-details\">\r\n              <h3 class=\"item-name\">${this.escapeHtml(item.name)}</h3>\r\n              <span class=\"item-type\">${this.escapeHtml(item.subject)} · ${this.escapeHtml(item.type)}</span>\r\n              <p class=\"item-desc\">${this.escapeHtml(item.description)}</p>\r\n            </div>\r\n          </article>\r\n        `).join('')}\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  renderSettingsPanel() {\r\n    const isMuted = soundEngine.isMuted();\r\n    const reducedMotion = Boolean(this.player.settings.reducedMotion);\r\n\r\n    return `\r\n      <div class=\"settings-form\">\r\n        <fieldset class=\"settings-group\">\r\n          <legend class=\"settings-legend\">Audio & Senses</legend>\r\n          <div class=\"setting-row\">\r\n            <label for=\"toggle-audio\" class=\"setting-label\">Sound Effects (Procedural FX)</label>\r\n            <button type=\"button\" id=\"toggle-audio\" class=\"btn-toggle ${isMuted ? 'muted' : 'active'}\">\r\n              ${isMuted ? getSvgIcon('audio-off', PALETTE.ERROR, 16) : getSvgIcon('audio-on', PALETTE.SUCCESS, 16)}\r\n              <span>${isMuted ? 'Muted' : 'Enabled'}</span>\r\n            </button>\r\n          </div>\r\n        </fieldset>\r\n\r\n        <fieldset class=\"settings-group\">\r\n          <legend class=\"settings-legend\">Motion & Accessibility</legend>\r\n          <div class=\"setting-row\">\r\n            <label for=\"toggle-motion\" class=\"setting-label\">Reduced Motion (No Screen Shake)</label>\r\n            <button type=\"button\" id=\"toggle-motion\" class=\"btn-toggle ${reducedMotion ? 'active' : ''}\">\r\n              <span>${reducedMotion ? 'Enabled (Calm)' : 'Standard'}</span>\r\n            </button>\r\n          </div>\r\n        </fieldset>\r\n\r\n        <fieldset class=\"settings-group\">\r\n          <legend class=\"settings-legend\">Child Privacy & Identity</legend>\r\n          <div class=\"setting-row\">\r\n            <div class=\"setting-label\">\r\n              <span>Adventurer Handle</span>\r\n              <small class=\"setting-subtext\">Zero PII. Randomly generated.</small>\r\n            </div>\r\n            <button type=\"button\" id=\"btn-reroll-name\" class=\"btn-secondary\">\r\n              Reroll Name\r\n            </button>\r\n          </div>\r\n        </fieldset>\r\n      </div>\r\n    `;\r\n  }\r\n\r\n  bindSettingsEvents(container) {\r\n    const audioBtn = container.querySelector('#toggle-audio');\r\n    if (audioBtn) {\r\n      audioBtn.addEventListener('click', () => {\r\n        const isMuted = soundEngine.toggleMute();\r\n        this.player.settings.audioMuted = isMuted;\r\n        soundEngine.playClick();\r\n        this.openTab('settings');\r\n        if (this.callbacks.onSettingsChange) {\r\n          this.callbacks.onSettingsChange(this.player.settings);\r\n        }\r\n      });\r\n    }\r\n\r\n    const motionBtn = container.querySelector('#toggle-motion');\r\n    if (motionBtn) {\r\n      motionBtn.addEventListener('click', () => {\r\n        this.player.settings.reducedMotion = !this.player.settings.reducedMotion;\r\n        soundEngine.playClick();\r\n        this.openTab('settings');\r\n        if (this.callbacks.onSettingsChange) {\r\n          this.callbacks.onSettingsChange(this.player.settings);\r\n        }\r\n      });\r\n    }\r\n\r\n    const rerollBtn = container.querySelector('#btn-reroll-name');\r\n    if (rerollBtn) {\r\n      rerollBtn.addEventListener('click', () => {\r\n        soundEngine.playChime();\r\n        if (this.callbacks.onRerollHandle) {\r\n          const newHandle = this.callbacks.onRerollHandle();\r\n          this.player.handle = newHandle;\r\n          const hudHandle = this.root.querySelector('#hud-handle');\r\n          if (hudHandle) hudHandle.textContent = newHandle;\r\n          this.openTab('settings');\r\n        }\r\n      });\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Opens the turn-based encounter question modal.\r\n   * @param {object} encounter\r\n   * @param {object} question (sanitized without answerKey)\r\n   * @param {(choiceId: string) => void} onSelectChoice\r\n   */\r\n  openEncounterModal(encounter, question, onSelectChoice) {\r\n    this.activeTab = 'encounter';\r\n    const container = this.root.querySelector('#panel-container');\r\n    const title = this.root.querySelector('#panel-title');\r\n    const body = this.root.querySelector('#panel-body');\r\n\r\n    if (!container || !title || !body) return;\r\n\r\n    soundEngine.playEncounterStart();\r\n    container.removeAttribute('hidden');\r\n\r\n    title.textContent = `Combat Encounter: ${encounter.name}`;\r\n\r\n    body.innerHTML = `\r\n      <div class=\"encounter-modal\">\r\n        <header class=\"encounter-enemy-header\">\r\n          <div class=\"enemy-info\">\r\n            <span class=\"enemy-name\">${this.escapeHtml(encounter.name)}</span>\r\n            <small class=\"enemy-type\">${this.escapeHtml(encounter.type.toUpperCase())} · ${this.escapeHtml(encounter.subjectId)}</small>\r\n          </div>\r\n          <div class=\"enemy-hp-track\">\r\n            <span>HP</span>\r\n            <div class=\"enemy-hp-bar\">\r\n              <div class=\"enemy-hp-fill\" id=\"enemy-hp-fill\" style=\"width: 100%\"></div>\r\n            </div>\r\n          </div>\r\n        </header>\r\n\r\n        <section class=\"question-card-prompt\" id=\"question-prompt\">\r\n          ${this.escapeHtml(question.prompt)}\r\n        </section>\r\n\r\n        <div class=\"choices-list\" id=\"choices-container\" role=\"radiogroup\" aria-label=\"Question Choices\">\r\n          ${question.choices.map(c => `\r\n            <button type=\"button\" class=\"choice-btn\" data-choice=\"${c.id}\" role=\"radio\" aria-checked=\"false\">\r\n              <span class=\"choice-key\">${c.id.toUpperCase()}</span>\r\n              <span class=\"choice-text\">${this.escapeHtml(c.text)}</span>\r\n            </button>\r\n          `).join('')}\r\n        </div>\r\n\r\n        <div id=\"encounter-feedback-slot\"></div>\r\n      </div>\r\n    `;\r\n\r\n    const choiceButtons = body.querySelectorAll('.choice-btn');\r\n    choiceButtons.forEach(btn => {\r\n      btn.addEventListener('click', () => {\r\n        const choiceId = btn.getAttribute('data-choice');\r\n        choiceButtons.forEach(b => (b.disabled = true));\r\n        if (onSelectChoice) {\r\n          onSelectChoice(choiceId);\r\n        }\r\n      });\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Displays answer feedback and explanation card in the encounter modal.\r\n   */\r\n  showAnswerFeedback(result, onNext) {\r\n    const body = this.root.querySelector('#panel-body');\r\n    const feedbackSlot = this.root.querySelector('#encounter-feedback-slot');\r\n    if (!feedbackSlot) return;\r\n\r\n    if (result.correct) {\r\n      soundEngine.playCorrect();\r\n    } else {\r\n      soundEngine.playWrong();\r\n    }\r\n\r\n    const enemyHpFill = this.root.querySelector('#enemy-hp-fill');\r\n    if (enemyHpFill && result.enemyHp !== undefined) {\r\n      enemyHpFill.style.width = `${Math.max(0, result.enemyHp * 50)}%`;\r\n    }\r\n\r\n    feedbackSlot.innerHTML = `\r\n      <aside class=\"feedback-card ${result.correct ? 'feedback-correct' : 'feedback-incorrect'}\">\r\n        <h4 class=\"feedback-title\">${result.correct ? '✔ Correct Answer!' : '✖ Academic Review Feedback'}</h4>\r\n        <p class=\"feedback-text\">${this.escapeHtml(result.explanation)}</p>\r\n        <button type=\"button\" class=\"feedback-action-btn\" id=\"feedback-next-btn\">\r\n          ${result.enemyDefeated ? 'Claim Victory' : (result.playerDefeated ? 'Recover at Sanctuary' : 'Next Question')}\r\n        </button>\r\n      </aside>\r\n    `;\r\n\r\n    const nextBtn = feedbackSlot.querySelector('#feedback-next-btn');\r\n    if (nextBtn) {\r\n      nextBtn.focus();\r\n      nextBtn.addEventListener('click', () => {\r\n        soundEngine.playClick();\r\n        if (onNext) onNext();\r\n      });\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Displays the Victory Celebration modal upon defeating the boss.\r\n   */\r\n  showVictoryModal(rewards, onDone) {\r\n    this.activeTab = 'victory';\r\n    const container = this.root.querySelector('#panel-container');\r\n    const title = this.root.querySelector('#panel-title');\r\n    const body = this.root.querySelector('#panel-body');\r\n\r\n    if (!container || !title || !body) return;\r\n\r\n    soundEngine.playFanfare();\r\n    container.removeAttribute('hidden');\r\n    title.textContent = 'Quest Complete!';\r\n\r\n    body.innerHTML = `\r\n      <article class=\"victory-card\">\r\n        <div class=\"victory-icon\">${getSvgIcon('trophy', PALETTE.GOLD, 48)}</div>\r\n        <h3 class=\"victory-title\">The Verdant Sanctuary Restored!</h3>\r\n        <p class=\"victory-desc\">\r\n          You answered every Governor's Cup question with precision, pacifying the Overgrown Guardian and restoring academic balance to Kentucky!\r\n        </p>\r\n        <div class=\"victory-rewards\">\r\n          <span>+${rewards.xp || 150} XP</span>\r\n          <span>+${rewards.gold || 50} Gold</span>\r\n        </div>\r\n        <button type=\"button\" class=\"feedback-action-btn\" id=\"victory-done-btn\">Return to Crossroads</button>\r\n      </article>\r\n    `;\r\n\r\n    const doneBtn = body.querySelector('#victory-done-btn');\r\n    if (doneBtn) {\r\n      doneBtn.focus();\r\n      doneBtn.addEventListener('click', () => {\r\n        this.closePanel();\r\n        if (onDone) onDone();\r\n      });\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Shows NPC dialogue modal (e.g. Elder Sage of Berea).\r\n   */\r\n  showNpcDialogueModal(npc, onAcceptQuest) {\r\n    this.activeTab = 'npc';\r\n    const container = this.root.querySelector('#panel-container');\r\n    const title = this.root.querySelector('#panel-title');\r\n    const body = this.root.querySelector('#panel-body');\r\n\r\n    if (!container || !title || !body) return;\r\n\r\n    soundEngine.playChime();\r\n    container.removeAttribute('hidden');\r\n    title.textContent = npc.name;\r\n\r\n    body.innerHTML = `\r\n      <article class=\"quest-card\">\r\n        <p class=\"quest-desc\" style=\"font-size: 14px; line-height: 1.5;\">${this.escapeHtml(npc.dialogue)}</p>\r\n        <footer class=\"quest-footer\" style=\"margin-top: 12px;\">\r\n          <button type=\"button\" class=\"btn-secondary\" id=\"npc-accept-btn\">Accept Quest & Explore</button>\r\n        </footer>\r\n      </article>\r\n    `;\r\n\r\n    const acceptBtn = body.querySelector('#npc-accept-btn');\r\n    if (acceptBtn) {\r\n      acceptBtn.focus();\r\n      acceptBtn.addEventListener('click', () => {\r\n        this.closePanel();\r\n        if (onAcceptQuest) onAcceptQuest();\r\n      });\r\n    }\r\n  }\r\n\r\n  showInteractionBanner(text) {\r\n    const banner = this.root.querySelector('#interaction-banner');\r\n    const content = this.root.querySelector('#interaction-text');\r\n    if (!banner || !content) return;\r\n\r\n    content.textContent = text;\r\n    banner.removeAttribute('hidden');\r\n  }\r\n\r\n  hideInteractionBanner() {\r\n    const banner = this.root.querySelector('#interaction-banner');\r\n    if (banner) {\r\n      banner.setAttribute('hidden', '');\r\n    }\r\n  }\r\n\r\n  escapeHtml(str) {\r\n    if (typeof str !== 'string') return '';\r\n    return str\r\n      .replace(/&/g, '&amp;')\r\n      .replace(/</g, '&lt;')\r\n      .replace(/>/g, '&gt;')\r\n      .replace(/\"/g, '&quot;')\r\n      .replace(/'/g, '&#39;');\r\n  }\r\n}\n\n/* --- APPLICATION ORCHESTRATOR --- */\n\n// src/client/app.js — Core Game Client Orchestrator\r\n// Connects Input, Multi-Zone World, Canvas 2D Engine, Audio, Encounters, and UI Overlay.\r\n\r\n\r\nconst STORAGE_KEY = 'quest_ky_guest_profile';\r\n\r\nclass GameApp {\r\n  constructor(canvasElement, uiRootElement) {\r\n    this.canvas = canvasElement;\r\n    this.uiRoot = uiRootElement;\r\n\r\n    // Load local guest profile or create new\r\n    this.player = this.loadProfile();\r\n\r\n    // Initialize subsystems\r\n    this.input = new InputManager();\r\n    this.renderer = new GameRenderer(this.canvas);\r\n    this.encounterEngine = new EncounterEngine(DUNGEON_ENCOUNTERS, SYNTHETIC_QUESTIONS);\r\n\r\n    this.ui = new UIManager(this.uiRoot, this.player, {\r\n      onSettingsChange: (settings) => this.saveProfile(),\r\n      onRerollHandle: () => {\r\n        const handle = generateAdventurerHandle();\r\n        this.player.handle = handle;\r\n        this.saveProfile();\r\n        return handle;\r\n      },\r\n    });\r\n\r\n    // Bind touch controls\r\n    const touchElements = this.ui.getTouchElements();\r\n    this.input.bindVirtualControls(touchElements);\r\n    this.input.initKeyboard();\r\n\r\n    // Apply audio preference\r\n    if (this.player.settings.audioMuted) {\r\n      soundEngine.toggleMute(true);\r\n    }\r\n\r\n    // Animation loop state\r\n    this.lastTime = 0;\r\n    this.animationFrameId = null;\r\n    this.running = false;\r\n\r\n    // Bind loop\r\n    this.tick = this.tick.bind(this);\r\n    this.onResize = this.onResize.bind(this);\r\n  }\r\n\r\n  loadProfile() {\r\n    try {\r\n      if (typeof localStorage !== 'undefined') {\r\n        const saved = localStorage.getItem(STORAGE_KEY);\r\n        if (saved) {\r\n          return JSON.parse(saved);\r\n        }\r\n      }\r\n    } catch {\r\n      // LocalStorage access restricted / private browsing fallback\r\n    }\r\n    return createDefaultPlayerProfile();\r\n  }\r\n\r\n  saveProfile() {\r\n    try {\r\n      if (typeof localStorage !== 'undefined') {\r\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(this.player));\r\n      }\r\n    } catch {\r\n      // Ignore storage write error\r\n    }\r\n  }\r\n\r\n  start() {\r\n    if (this.running) return;\r\n    this.running = true;\r\n\r\n    // Setup resize listener\r\n    if (typeof window !== 'undefined') {\r\n      window.addEventListener('resize', this.onResize);\r\n      this.onResize();\r\n    }\r\n\r\n    this.lastTime = performance.now();\r\n    this.animationFrameId = requestAnimationFrame(this.tick);\r\n  }\r\n\r\n  stop() {\r\n    this.running = false;\r\n    if (this.animationFrameId) {\r\n      cancelAnimationFrame(this.animationFrameId);\r\n    }\r\n    if (typeof window !== 'undefined') {\r\n      window.removeEventListener('resize', this.onResize);\r\n    }\r\n    this.input.destroy();\r\n  }\r\n\r\n  onResize() {\r\n    if (!this.canvas || typeof window === 'undefined') return;\r\n    const container = this.canvas.parentElement || document.body;\r\n    const width = container.clientWidth || window.innerWidth;\r\n    const height = (container.clientHeight || window.innerHeight) * 0.65;\r\n    this.renderer.handleResize(width, height);\r\n  }\r\n\r\n  /**\r\n   * Handles player interaction button trigger [ACT].\r\n   */\r\n  handleAction() {\r\n    const interaction = this.renderer.activeInteraction;\r\n    if (!interaction) return;\r\n\r\n    if (interaction.type === 'npc') {\r\n      this.ui.showNpcDialogueModal(interaction, () => {\r\n        // Activate starter quest \"Flora of the Verdant Wilds\"\r\n        const quest = this.player.quests.find(q => q.subjectId === 'science');\r\n        if (quest && quest.status !== 'completed') {\r\n          quest.status = 'active';\r\n          quest.progress = 'Investigate the Verdant Sanctuary';\r\n          this.saveProfile();\r\n        }\r\n        this.ui.showInteractionBanner('Quest Accepted: Take the northern trail to the Verdant Sanctuary!');\r\n      });\r\n      return;\r\n    }\r\n\r\n    if (interaction.type === 'shrine') {\r\n      soundEngine.playChime();\r\n      this.ui.showInteractionBanner(\r\n        `Examining ${interaction.label}: Gateway to ${interaction.subject.realm}.`\r\n      );\r\n      return;\r\n    }\r\n\r\n    if (interaction.type === 'encounter') {\r\n      this.startCombatEncounter(interaction);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Launches a turn-based combat encounter.\r\n   */\r\n  startCombatEncounter(interaction) {\r\n    this.encounterEngine.startEncounter(interaction.index);\r\n    const encounter = this.encounterEngine.activeEncounter;\r\n    const question = this.encounterEngine.activeQuestion;\r\n\r\n    this.ui.openEncounterModal(encounter, question, (choiceId) => {\r\n      this.handleEncounterChoice(choiceId, interaction);\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Processes player answer choice in encounter.\r\n   */\r\n  handleEncounterChoice(choiceId, interaction) {\r\n    const result = this.encounterEngine.submitAnswer(choiceId);\r\n\r\n    // Update player health in profile and HUD\r\n    this.player.hp = Math.max(1, this.encounterEngine.playerHp);\r\n    this.ui.updatePlayerStats(this.player);\r\n\r\n    this.ui.showAnswerFeedback(result, () => {\r\n      this.handleEncounterAdvance(result, interaction);\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Advances encounter to next step, victory, or retry.\r\n   */\r\n  handleEncounterAdvance(result, interaction) {\r\n    if (result.enemyDefeated) {\r\n      interaction.defeated = true;\r\n      this.ui.closePanel();\r\n\r\n      if (this.encounterEngine.completed) {\r\n        // Complete the quest and award rewards\r\n        this.completeQuestAndReward();\r\n      } else {\r\n        soundEngine.playChime();\r\n        this.ui.showInteractionBanner(`${interaction.label} overcome! Continue forward.`);\r\n      }\r\n      return;\r\n    }\r\n\r\n    if (result.playerDefeated) {\r\n      // Safe recovery without soft locks: return to Hub\r\n      this.ui.closePanel();\r\n      soundEngine.playAlert();\r\n      this.player.hp = this.player.maxHp;\r\n      this.ui.updatePlayerStats(this.player);\r\n      this.renderer.changeZone('hub', 152, 120);\r\n      this.encounterEngine.retry();\r\n      this.ui.showInteractionBanner('The Elder Sage’s ward returns you to Berea Crossroads to recover.');\r\n      return;\r\n    }\r\n\r\n    // Next question for boss\r\n    this.encounterEngine.advance();\r\n    const encounter = this.encounterEngine.activeEncounter;\r\n    const question = this.encounterEngine.activeQuestion;\r\n    this.ui.openEncounterModal(encounter, question, (choiceId) => {\r\n      this.handleEncounterChoice(choiceId, interaction);\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Awards quest completion rewards upon defeating the boss.\r\n   */\r\n  completeQuestAndReward() {\r\n    const quest = this.player.quests.find(q => q.subjectId === 'science');\r\n    if (quest) {\r\n      quest.status = 'completed';\r\n      quest.progress = 'Sanctuary Restored (Completed)';\r\n    }\r\n\r\n    const rewardXp = 150;\r\n    const rewardGold = 50;\r\n\r\n    this.player.xp = (this.player.xp || 0) + rewardXp;\r\n    this.player.gold += rewardGold;\r\n\r\n    // Level up check\r\n    if (this.player.xp >= 100) {\r\n      this.player.level = Math.floor(this.player.xp / 100) + 1;\r\n    }\r\n\r\n    // Add unique completion relic to inventory\r\n    const relic = {\r\n      id: 'item_guardian_bloom',\r\n      name: \"Guardian's Living Bloom\",\r\n      type: 'artifact',\r\n      slot: 'trophy',\r\n      subject: 'Science',\r\n      color: PALETTE.SCIENCE,\r\n      icon: 'trophy',\r\n      description: 'Awarded for restoring balance to the Overgrown Guardian in the Verdant Sanctuary.',\r\n      equipped: false,\r\n    };\r\n\r\n    if (!this.player.inventory.some(i => i.id === relic.id)) {\r\n      this.player.inventory.push(relic);\r\n    }\r\n\r\n    this.saveProfile();\r\n    this.ui.updatePlayerStats(this.player);\r\n\r\n    this.ui.showVictoryModal({ xp: rewardXp, gold: rewardGold }, () => {\r\n      this.renderer.changeZone('hub', 152, 120);\r\n    });\r\n  }\r\n\r\n  tick(currentTime) {\r\n    if (!this.running) return;\r\n\r\n    const dt = Math.min((currentTime - this.lastTime) / 1000, 0.1);\r\n    this.lastTime = currentTime;\r\n\r\n    // Handle [ACT] interact button trigger\r\n    if (this.input.isJustPressed('action') && !this.ui.activeTab) {\r\n      this.handleAction();\r\n    }\r\n\r\n    // Handle [MENU] button trigger\r\n    if (this.input.isJustPressed('menu')) {\r\n      if (this.ui.activeTab && this.ui.activeTab !== 'encounter') {\r\n        this.ui.closePanel();\r\n      } else if (!this.ui.activeTab) {\r\n        this.ui.openTab('settings');\r\n      }\r\n    }\r\n\r\n    // Update game physics, collisions, zone transitions, and camera\r\n    this.renderer.update(dt, this.input, Boolean(this.player.settings.reducedMotion));\r\n\r\n    // Clear just-pressed buffer\r\n    this.input.update();\r\n\r\n    // Render frame\r\n    this.renderer.render(currentTime);\r\n\r\n    this.animationFrameId = requestAnimationFrame(this.tick);\r\n  }\r\n}";

export function createHtmlShell() {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
  <meta name="theme-color" content="${PALETTE.BG_DARK}">
  <meta name="description" content="QUEST: Kentucky — Governor's Cup Middle Grades RPG">
  <link rel="manifest" href="/manifest.webmanifest">
  <title>QUEST: Kentucky — Governor's Cup RPG</title>
  <style>
${GAME_CSS}
  </style>
</head>
<body>
  <main id="app-root">
    <div id="ui-root"></div>
    <div role="region" aria-label="Kentucky World Viewport" class="canvas-container">
      <canvas id="game-canvas" width="${VIEWPORT.LOGICAL_WIDTH}" height="${VIEWPORT.LOGICAL_HEIGHT}"></canvas>
    </div>
  </main>

  <script type="module">
${CLIENT_BUNDLE}

    if ('serviceWorker' in navigator) {
      window.addEventListener('load', () => {
        navigator.serviceWorker.register('/sw.js').catch(() => {});
      });
    }

    window.addEventListener('DOMContentLoaded', () => {
      const canvas = document.getElementById('game-canvas');
      const uiRoot = document.getElementById('ui-root');
      if (canvas && uiRoot && typeof GameApp !== 'undefined') {
        const app = new GameApp(canvas, uiRoot);
        app.start();
        window.__QUEST_APP__ = app;
      }
    });
  </script>
</body>
</html>`;
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const db = env && env.DB ? new DatabaseAdapter(env.DB) : defaultDb;

    const securityHeaders = {
      'X-Content-Type-Options': 'nosniff',
      'X-Frame-Options': 'DENY',
      'Referrer-Policy': 'strict-origin-when-cross-origin',
    };

    // Health check endpoint (Phase 4)
    if (url.pathname === '/api/health') {
      return new Response(JSON.stringify({
        status: 'ok',
        game: 'QUEST: Kentucky',
        gradeBand: '6-8',
        phase: 4,
        mode: 'd1-persistence-and-spaced-repetition',
      }), {
        headers: {
          'Content-Type': 'application/json',
          ...securityHeaders,
        },
      });
    }

    // Public Question Delivery endpoint (Sanitized, Rights-Gated)
    if (url.pathname === '/api/questions' && request.method === 'GET') {
      const subjectFilter = url.searchParams.get('subject');
      const gradeBandFilter = url.searchParams.get('gradeBand');

      const approvedQuestions = QUESTION_CATALOG.filter((q) => {
        if (!q.active || q.rightsStatus !== 'approved') return false;
        if (subjectFilter && q.subject !== subjectFilter) return false;
        if (gradeBandFilter && q.gradeBand !== gradeBandFilter) return false;
        return true;
      });

      return new Response(JSON.stringify({
        count: approvedQuestions.length,
        questions: approvedQuestions.map(sanitizeQuestionForClient),
      }), {
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': 'public, max-age=600',
          ...securityHeaders,
        },
      });
    }

    // Staging Question Validation Endpoint (Pre-import Review Aid)
    if (url.pathname === '/api/questions/validate' && request.method === 'POST') {
      try {
        const body = await request.json();
        const items = Array.isArray(body?.questions)
          ? body.questions
          : body?.question
            ? [body.question]
            : null;

        if (!items) {
          return new Response(JSON.stringify({ error: 'Payload must include question object or questions array' }), {
            status: 400,
            headers: { 'Content-Type': 'application/json', ...securityHeaders },
          });
        }

        const results = items.map((item) => {
          const val = validateQuestion(item);
          const dup = detectDuplicates(item, QUESTION_CATALOG);
          return {
            id: item?.id || 'unknown',
            valid: val.valid,
            errors: val.errors,
            rightsStatus: val.rightsStatus,
            duplicateWarnings: dup.warnings,
          };
        });

        const allValid = results.every((r) => r.valid);
        return new Response(JSON.stringify({
          valid: allValid,
          results,
        }), {
          headers: { 'Content-Type': 'application/json', ...securityHeaders },
        });
      } catch {
        return new Response(JSON.stringify({ error: 'Invalid JSON payload' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json', ...securityHeaders },
        });
      }
    }

    // Authorized Content Reviewer Import Endpoint (Rights Gate Enforcement)
    if (url.pathname === '/api/questions/import' && request.method === 'POST') {
      const role = request.headers.get('x-reviewer-role');
      if (!role || (role !== 'reviewer' && role !== 'content_admin')) {
        return new Response(JSON.stringify({ error: 'Unauthorized: Content reviewer role required' }), {
          status: 403,
          headers: { 'Content-Type': 'application/json', ...securityHeaders },
        });
      }

      try {
        const body = await request.json();
        if (!body || !Array.isArray(body.questions)) {
          return new Response(JSON.stringify({ error: 'Payload must contain a questions array' }), {
            status: 400,
            headers: { 'Content-Type': 'application/json', ...securityHeaders },
          });
        }

        const result = importQuestions(body.questions, QUESTION_CATALOG);
        if (result.imported.length > 0) {
          QUESTION_CATALOG.push(...result.imported);
        }

        return new Response(JSON.stringify({
          success: result.success,
          importedCount: result.imported.length,
          rejectedCount: result.rejected.length,
          imported: result.imported.map(sanitizeQuestionForClient),
          rejected: result.rejected,
          warnings: result.warnings,
        }), {
          headers: { 'Content-Type': 'application/json', ...securityHeaders },
        });
      } catch {
        return new Response(JSON.stringify({ error: 'Invalid JSON payload' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json', ...securityHeaders },
        });
      }
    }

    if (url.pathname === '/api/regions') {
      return new Response(JSON.stringify({
        regions: Object.values(SUBJECTS),
      }), {
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': 'public, max-age=3600',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/api/quests') {
      return new Response(JSON.stringify({
        quests: STARTER_QUESTS,
      }), {
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': 'public, max-age=3600',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/api/encounters') {
      const questionMap = new Map(QUESTION_CATALOG.map((q) => [q.id, q]));
      const sanitizedEncounters = DUNGEON_ENCOUNTERS.map((enc) => {
        let question = null;
        if (enc.questionId) {
          question = sanitizeQuestionForClient(questionMap.get(enc.questionId));
        }
        return {
          ...enc,
          question,
        };
      });

      return new Response(JSON.stringify({
        dungeon: 'The Verdant Sanctuary',
        encounters: sanitizedEncounters,
      }), {
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': 'public, max-age=3600',
          ...securityHeaders,
        },
      });
    }

    // Student Concept Mastery Progress endpoint across the 5 KAAC subject realms
    if (url.pathname === '/api/progress' && request.method === 'GET') {
      const userId = url.searchParams.get('userId') || request.headers.get('x-guest-id') || 'guest_default';
      const masteryList = await db.getUserMasteryList(userId);
      const progress = computeSubjectProgress(masteryList, QUESTION_CATALOG);
      const totalMastered = masteryList.filter((m) => m.isMastered).length;
      const activeDueCount = getDueReviews(masteryList, Date.now()).length;

      return new Response(JSON.stringify({
        userId,
        totalMastered,
        activeDueCount,
        progress,
      }), {
        headers: {
          'Content-Type': 'application/json',
          ...securityHeaders,
        },
      });
    }

    // Spaced Repetition Due Reviews endpoint
    if (url.pathname === '/api/review/due' && request.method === 'GET') {
      const userId = url.searchParams.get('userId') || request.headers.get('x-guest-id') || 'guest_default';
      const masteryList = await db.getUserMasteryList(userId);
      const dueRecords = getDueReviews(masteryList, Date.now());

      const dueConceptIds = new Set(dueRecords.map((r) => r.conceptId));
      const eligibleQuestions = QUESTION_CATALOG.filter((q) =>
        q.active &&
        q.rightsStatus === 'approved' &&
        Array.isArray(q.conceptIds) &&
        q.conceptIds.some((cid) => dueConceptIds.has(cid))
      );

      return new Response(JSON.stringify({
        userId,
        count: dueRecords.length,
        dueConcepts: dueRecords,
        eligibleQuestions: eligibleQuestions.map(sanitizeQuestionForClient),
      }), {
        headers: {
          'Content-Type': 'application/json',
          ...securityHeaders,
        },
      });
    }

    // Server-Authoritative Answer Validation endpoint with D1 Persistence & Spaced Repetition
    if (url.pathname === '/api/answers' && request.method === 'POST') {
      try {
        const body = await request.json();
        const { questionId, selectedChoiceId, idempotencyKey, assisted } = body || {};

        if (idempotencyKey && IDEMPOTENCY_STORE.has(idempotencyKey)) {
          return new Response(JSON.stringify(IDEMPOTENCY_STORE.get(idempotencyKey)), {
            headers: { 'Content-Type': 'application/json', ...securityHeaders },
          });
        }

        const question = QUESTION_CATALOG.find((q) => q.id === questionId);
        if (!question) {
          return new Response(JSON.stringify({ error: 'Question not found' }), {
            status: 404,
            headers: { 'Content-Type': 'application/json', ...securityHeaders },
          });
        }

        // Rights gate check: item must be active and approved to be answerable
        if (!question.active || question.rightsStatus !== 'approved') {
          return new Response(JSON.stringify({ error: 'Question is not active or rights status is unapproved' }), {
            status: 403,
            headers: { 'Content-Type': 'application/json', ...securityHeaders },
          });
        }

        const validChoice = Array.isArray(question.choices) && question.choices.some((c) => c.id === selectedChoiceId);
        if (!validChoice) {
          return new Response(JSON.stringify({ error: 'Invalid choice ID' }), {
            status: 400,
            headers: { 'Content-Type': 'application/json', ...securityHeaders },
          });
        }

        const userId = body?.userId || body?.sessionId || request.headers.get('x-guest-id') || 'guest_default';
        const verdict = await db.processAnswerAttempt({
          userId,
          question,
          selectedChoiceId,
          assisted: Boolean(assisted),
          sessionId: body?.sessionId || null,
          idempotencyKey,
          now: Date.now(),
        });

        if (idempotencyKey) {
          IDEMPOTENCY_STORE.set(idempotencyKey, verdict);
        }

        return new Response(JSON.stringify(verdict), {
          headers: { 'Content-Type': 'application/json', ...securityHeaders },
        });
      } catch {
        return new Response(JSON.stringify({ error: 'Invalid JSON payload' }), {
          status: 400,
          headers: { 'Content-Type': 'application/json', ...securityHeaders },
        });
      }
    }

    if (url.pathname === '/api/session') {
      const guestId = (crypto && crypto.randomUUID) ? crypto.randomUUID() : 'guest_' + Math.random().toString(36).substring(2, 10);
      return new Response(JSON.stringify({
        guestId,
        gradeBand: '6-8',
        authenticated: false,
      }), {
        headers: {
          'Content-Type': 'application/json',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/manifest.webmanifest' || url.pathname === '/manifest.json') {
      return new Response(JSON.stringify(createManifest()), {
        headers: {
          'Content-Type': 'application/manifest+json; charset=utf-8',
          'Cache-Control': 'public, max-age=86400',
          ...securityHeaders,
        },
      });
    }

    if (url.pathname === '/sw.js') {
      return new Response(createServiceWorker(), {
        headers: {
          'Content-Type': 'application/javascript; charset=utf-8',
          'Cache-Control': 'no-cache',
          ...securityHeaders,
        },
      });
    }

    const html = createHtmlShell();
    return new Response(html, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'public, max-age=3600',
        ...securityHeaders,
      },
    });
  },
};
